                if (map.loopX) nx = (nx + w) % w;
                if (map.loopY) ny = (ny + h) % h;
                if (nx < 0 || ny < 0 || nx >= w || ny >= h) continue;
                const k = nx + ny * w;
                if (seen[k] || !map.canStep(x, y, dir)) continue;
                seen[k] = 1;
                count++;
