            x: number(raw.x, 0), y: number(raw.y, 0),
            time: DocsDoodads.TimeOfDay.wrap(number(raw.time, 480)),
            season: Math.max(0, Math.floor(number(raw.season, 0))),
            weather: { type, power: Math.max(0, Math.min(9, number(weather.power, 0))) },
