            cloudSpeed: num(s.cloudSpeed, d.cloudSpeed, 0, 5),
            mist: num(s.mist, d.mist, 0, 1),
            mistHeight: num(s.mistHeight, d.mistHeight, 0.25, 10),
            minimap: s.minimap === true,
            battleBack: s.battleBack === true,
