            const du = dx * cam.axis.x + dy * cam.axis.y, dw = dx * cam.ahead.x + dy * cam.ahead.y;
            const t = nearest(dw * dw + dz * dz, 2 * (cw * dw + cz * dz), cw * cw + C.z * C.z + 2 * C.z * R);
