            const files = this.fs.readdirSync(dir)
                .filter(f => f.startsWith(prefix + '.') && f.endsWith(ending))
                .map(f => ({ name: f, time: this.fs.statSync(this.path.join(dir, f)).mtimeMs }))
                .sort((a, b) => b.time - a.time);
