            size: (a, b) => ((Number(b.width) || 0) * (Number(b.height) || 0)) - ((Number(a.width) || 0) * (Number(a.height) || 0)),
            placed: (a, b) => ((b.usage && b.usage.useCount) || 0) - ((a.usage && a.usage.useCount) || 0),
