Object.assign(DocsDoodads.Workspace, {
    _creator: null,

    creatorAnimations: [['walk', 'Walk'], ['idle', 'Idle'], ['run', 'Run'], ['slash', 'Slash'], ['thrust', 'Thrust'], ['spellcast', 'Spellcast'],
        ['shoot', 'Shoot'], ['hurt', 'Hurt'], ['sit', 'Sit'], ['emote', 'Emote'], ['jump', 'Jump'], ['climb', 'Climb'], ['combat', 'Combat'], ['slash_reverse', 'Backswing']],
    creatorFps: { walk: 10, run: 12, idle: 3, combat: 3, sit: 2, emote: 3 },

    // The library the open creator builds from (DocsDoodads.CreatorKits): LPC unless it was opened for another.
    creatorKit() {
        const K = DocsDoodads.CreatorKits;
        return K[(this._creator && this._creator.kit) || 'lpc'] || K.lpc;
    },

    creatorSlots() {
        return this.creatorKit().slots;
    },

    creatorIndex() {
        return this.creatorKit().index(this);
    },

    // Each kit's images in two caches, within the kit's memory (cacheMB, half each): raw, the library's files
    // as decoded (masks too), so a new colour doesn't read and inflate a file again; layers, the recoloured
    // layers by file and colours. A rescan empties them.
    creatorImageCaches(kitId) {
        const C = DocsDoodads.LpcCompose, K = DocsDoodads.CreatorKits[kitId] || DocsDoodads.CreatorKits.lpc;
        const all = this._creatorImageCaches || (this._creatorImageCaches = {});
        if (!all[kitId]) {
            const half = (K.cacheMB || 96) * 1024 * 1024 / 2;
            all[kitId] = { raw: C.newCache(4000, half), layers: C.newCache(4000, half) };
        }
        return all[kitId];
    },

    resetCreatorImageCaches(kitId) {
        if (this._creatorImageCaches) delete this._creatorImageCaches[kitId];
        if (this.forgetCreatorThumbs) this.forgetCreatorThumbs(kitId);
    },

    // A library file decoded once: load() reads it; null (unreadable) isn't kept.
    creatorRawImage(kitId, file, load) {
        return DocsDoodads.LpcCompose.cached(this.creatorImageCaches(kitId).raw, file, load);
    },

    // ---- The library switcher ----

    // The kits whose library has been scanned, in the Characters card's order.
    creatorKitsReady() {
        const K = DocsDoodads.CreatorKits;
        return ['mz', 'lpc', 'memao'].filter(id => K[id] && K[id].index(this)).map(id => K[id]);
    },

    // The one opened last (Character Creator... in the palette), if its library is still there.
    lastCreatorKit() {
        const ready = this.creatorKitsReady().map(k => k.id), last = DocsDoodads.Ui.prefs().creatorKit;
        return ready.includes(last) ? last : ready[0] || 'lpc';
    },

    creatorSwitcherHtml() {
        const kits = this.creatorKitsReady(), now = this.creatorKit().id;
        if (kits.length < 2) return '';
        return `<select class="dd-cr-kit" id="dd-cr-kit" aria-label="Library" title="Make the character from another library (the name is kept)">${kits.map(k => `<option value="${k.id}"${k.id === now ? ' selected' : ''}>${escapeHtml(k.switchLabel)}</option>`).join('')}</select>`;
    },

    // Another library in the same window: the name is kept, and each library's character is kept for coming back.
    creatorSwitchKit(kitId) {
        const c = this._creator;
        if (!c || !DocsDoodads.CreatorKits[kitId] || kitId === c.kit) return false;
        const kept = this._creatorKept || (this._creatorKept = {});
        kept[c.kit] = c.state;
        const name = c.name;
        if (!this.openCreator(kept[kitId] || null, kitId)) return false;
        this._creator.name = name;
        this.renderCreator();
        this.creatorSay(this.creatorKit().title);
        return true;
    },

    // The safe-to-encrypt switch (LPC only).
    creatorSafeOnly() {
        return this.creatorKit().safeSwitch ? this.lpcSafeOnly() : false;
    },

    openCreator(state, kit = 'lpc') {
        if (typeof document === 'undefined') return null;
        const K = DocsDoodads.CreatorKits[kit] || DocsDoodads.CreatorKits.lpc;
        const S = K.slots;
        const index = K.index(this);
        if (!index) { K.noLibrary(this); return null; }
        if (S.useIndex) S.useIndex(index);
        const safeOnly = K.safeSwitch ? this.lpcSafeOnly() : false;
        const was = this._creator && (this._creator.kit || 'lpc') === K.id ? this._creator : null;
        this._creator = {
            kit: K.id,
            state: state || (was && was.state) || S.newState(index, S.bodies[0][0], safeOnly),
            name: was ? was.name : '', anim: 'walk', dir: 'down', frame: 0,
            tabs: { body: 0, outfit: 0 }, cursor: { card: 'body', row: 0 }, showBody: true, addons: true, shadow: true, pop: null
        };
        this.closeLpcCard();
        DocsDoodads.Ui.setPref('creatorKit', K.id);
        this.creatorLiveRegion();
        this.renderCreator();
        this.startCreatorLoop();
        // Made smaller or bigger, the window changes between one card and two at once.
        if (!this._creatorResize && typeof window !== 'undefined' && window.addEventListener) {
            this._creatorResize = () => { if (this._creator && this.creatorOpen() && this.creatorNarrow() !== Boolean(this._creator.narrow)) this.renderCreator(); };
            window.addEventListener('resize', this._creatorResize);
        }
        DocsDoodads.Ui.sound('ok');
        return this._creator;
    },

    closeCreator() {
        const el = typeof document !== 'undefined' ? document.getElementById('dd-creator') : null;
        if (el && el.parentNode) el.parentNode.removeChild(el);
        this.stopCreatorLoop();
        if (this._creatorKeys && typeof window !== 'undefined') window.removeEventListener('keydown', this._creatorKeys, true);
        this._creatorKeys = null;
        if (this._creatorResize && typeof window !== 'undefined') window.removeEventListener('resize', this._creatorResize);
        this._creatorResize = null;
        if (this._creatorLive && this._creatorLive.parentNode) this._creatorLive.parentNode.removeChild(this._creatorLive);
        this._creatorLive = null;
        if (this._creator) this._creator.open = false;
    },

    creatorOpen() {
        return Boolean(typeof document !== 'undefined' && document.getElementById('dd-creator'));
    },

    // The rows of a card's current tab (the body tab starts with the body type).
    creatorRows(cardKey) {
        const S = this.creatorSlots(), c = this._creator;
        const card = S.cards.find(x => x.key === cardKey);
        const tab = card.tabs[c.tabs[cardKey]];
        // A kit can leave a row out (Memao's prop rows when the pack has one prop of that kind).
        const index = S.shown ? this.creatorIndex() : null;
        const rows = tab.slots.filter(s => !S.shown || S.shown(index, s, c.state.body)).map(s => Object.assign({ card: cardKey }, s));
        if (cardKey === 'body' && tab.key === 'body') rows.unshift({ key: '_body', label: 'Body type', card: 'body', special: true });
        return rows;
    },

    // What a row shows: value, the swatch's channel and colour, whether it can change. The swatch shows the
    // row's current colour channel (c.channels[row], changed with C or a long press of the pad's A): MZ's
    // colour slots, or LPC's second colour (eyes, trim).
    creatorRowView(row) {
        const S = this.creatorSlots(), c = this._creator, index = this.creatorIndex();
        if (row.key === '_body') {
            const label = (S.bodies.find(b => b[0] === c.state.body) || [c.state.body, c.state.body])[1];
            return { value: label, channel: -1, off: false, usable: [] };
        }
        const options = S.options(index, row, c.state.body, this.creatorSafeOnly());
        const pick = c.state.slots[row.key];
        const part = pick && index.parts.find(p => p.id === pick.id);
        const value = part ? part.name : (options.length ? 'None' : 'Nothing for this body');
        const channels = part && S.channels ? S.channels(index, part) : null;
        const usable = !part ? [] : channels ? channels.map((_, i) => i) : [0, 1].filter(ch => S.colours(index, part, ch).length);
        const chosen = c.channels && c.channels[row.key];
        const channel = usable.includes(chosen) ? chosen : usable.length ? usable[0] : -1;
        const colourName = channel >= 0 ? this.creatorColourOf(row.key, channel) : '';
        const addonOff = row.addon && !c.addons;
        const channelLabel = channel < 0 ? '' : channels && channels[channel] ? channels[channel].label : channel === 1 && row.colour2 ? row.colour2 : row.label;
        const view = { value, part, channel, channels: channels || [], usable, channelLabel, colourName, colour: channel >= 0 ? S.swatch(index, part, colourName, channel) : '',
            off: !options.length || addonOff, count: options.length, position: part ? options.findIndex(p => p.id === part.id) + 1 : 0 };
        // Memao's linked rows: { lead, linked, colour (the lead's swatch) }; linked, there is no swatch of its own.
        const link = S.linkOf ? S.linkOf(c.state, row.key) : null;
        if (link) {
            view.link = link;
            if (link.linked) {
                const lead = c.state.slots[link.lead];
                link.colour = lead && lead.colour ? S.swatch(index, part, lead.colour, 0) : '';
                Object.assign(view, { channel: -1, usable: [], colourName: '', colour: '' });
            }
        }
        return view;
    },

    // What a screen reader hears for a row: "Hair: Emo Left, 12 of 40", "Body type: Female, 2 of 6".
    creatorDescribe(rowKey) {
        const S = this.creatorSlots(), c = this._creator;
        if (rowKey === '_body') {
            const at = S.bodies.findIndex(b => b[0] === c.state.body);
            return `Body type: ${at >= 0 ? S.bodies[at][1] : c.state.body}, ${at + 1} of ${S.bodies.length}`;
        }
        const slot = S.slot(rowKey);
        const v = this.creatorRowView(Object.assign({ key: rowKey }, slot));
        return `${slot ? slot.label : rowKey}: ${v.value}` + (v.position ? `, ${v.position} of ${v.count}` : '');
    },

    // "Hair colour: auburn"; MZ's numbered colours as "colour 3 of 30", its own as "as drawn".
    creatorDescribeColour(rowKey) {
        const S = this.creatorSlots();
        const v = this.creatorRowView(Object.assign({ key: rowKey }, S.slot(rowKey)));
        if (v.channel < 0) return '';
        let words = v.colourName ? v.colourName.replace(/_/g, ' ') : 'as drawn';
        if (/^\w+:\d+$/.test(v.colourName || '')) {
            const list = S.colours(this.creatorIndex(), v.part, v.channel).filter(Boolean);
            words = `colour ${list.indexOf(v.colourName) + 1} of ${list.length}`;
        }
        return `${v.channelLabel} colour: ${words}`;
    },

    // The live region beside the window (outside it, so rebuilding the window doesn't recreate it): what
    // changed, read out by screen readers.
    creatorLiveRegion() {
        if (typeof document === 'undefined') return null;
        if (!this._creatorLive) {
            const live = document.createElement('div');
            live.id = 'dd-cr-live';
            if (live.setAttribute) { live.setAttribute('role', 'status'); live.setAttribute('aria-live', 'polite'); }
            live.style.cssText = 'position: fixed; left: -10000px; top: 0; width: 1px; height: 1px; overflow: hidden;';
            document.body.appendChild(live);
            this._creatorLive = live;
        }
        return this._creatorLive;
    },

    creatorSay(text) {
        const live = this.creatorLiveRegion();
        if (!live || !text) return '';
        live.textContent = String(text);
        return live.textContent;
    },

    // A row's colour on one channel: the kit's (MZ's shared colour slots), or the pick's colour / colour2.
    creatorColourOf(rowKey, channel) {
        const S = this.creatorSlots(), c = this._creator;
        if (S.getColour) return S.getColour(c.state, this.creatorIndex(), rowKey, channel);
        const pick = c.state.slots[rowKey] || {};
        return (channel === 1 ? pick.colour2 : pick.colour) || '';
    },

    // ---- Changing the character ----

    // say: what a screen reader hears about the change (the live region under the stage).
    creatorChanged(sound = 'cursor', say) {
        const c = this._creator;
        if (!c) return;
        c.composed = null;
        c.credits = null;
        DocsDoodads.Ui.sound(sound);
        this.renderCreator();
        if (say) this.creatorSay(say);
    },

    creatorStep(rowKey, dir) {
        const S = this.creatorSlots(), c = this._creator, index = this.creatorIndex(), safe = this.creatorSafeOnly();
        this.creatorRemember();
        if (rowKey === '_body') {
            const list = S.bodies.map(b => b[0]);
            const next = list[(list.indexOf(c.state.body) + dir + list.length) % list.length];
            c.state = S.setBody(c.state, index, next, safe);
        } else {
            S.step(c.state, index, rowKey, dir, safe);
        }
        this.creatorChanged('cursor', this.creatorDescribe(rowKey));
    },

    // name: set that colour (or, for the kit's colour slots, '' for as drawn); otherwise step through them.
    creatorColour(rowKey, dir, name, channel) {
        const S = this.creatorSlots(), c = this._creator, index = this.creatorIndex();
        const view = this.creatorRowView(Object.assign({ key: rowKey }, S.slot(rowKey)));
        if (view.link && view.link.linked) { this.creatorSay(`${S.slot(rowKey).label} takes the ${S.slot(view.link.lead).label.toLowerCase()} colour: K for its own`); return; }
        if (view.channel < 0) return;
        const ch = channel === undefined ? view.channel : channel;
        this.creatorRemember();
        const pick = c.state.slots[rowKey];
        if (name !== undefined && name !== null) {
            if (S.setColour) S.setColour(c.state, index, rowKey, ch, name);
            else pick[ch === 1 ? 'colour2' : 'colour'] = name;
        } else S.stepColour(c.state, index, rowKey, dir, ch);
        c.channels = Object.assign({}, c.channels, { [rowKey]: ch });
        this.creatorChanged('cursor', this.creatorDescribeColour(rowKey));
    },

    // C (or a long press of the pad's A): the cursor row's swatch goes to its next colour channel.
    creatorNextChannel(rowKey) {
        const S = this.creatorSlots(), c = this._creator;
        const view = this.creatorRowView(Object.assign({ key: rowKey }, S.slot(rowKey)));
        if (view.usable.length < 2) return false;
        const next = view.usable[(view.usable.indexOf(view.channel) + 1) % view.usable.length];
        c.channels = Object.assign({}, c.channels, { [rowKey]: next });
        DocsDoodads.Ui.sound('cursor');
        this.renderCreator();
        this.creatorSay(this.creatorDescribeColour(rowKey));
        return true;
    },

    // "Show all parts": the safe-to-encrypt switch off, saying what that means and how to turn it back on.
    creatorShowAllParts() {
        this.setLpcSafeOnly(false);
        const s = DocsDoodads.Lpc.summary(this.lpcIndex(), false);
        this.showToast(`Showing all ${s ? s.parts : ''} parts. Characters with CC-BY or CC-BY-SA art can't be in a game deployed with "Encrypt image files" (the export says which). Tick "Only art safe to encrypt" at the top to go back.`, 'info');
        this.creatorChanged();
    },

    creatorRecipe() {
        const c = this._creator;
        return this.creatorSlots().toRecipe(c.state, { showBody: c.showBody, addons: c.addons });
    },

    // The sheet of the current animation (composed once per change; the compositor caches the layers).
    creatorComposed() {
        const c = this._creator;
        if (!c.composed || c.composed.anim !== c.anim) {
            const out = this.creatorKit().draw(this, this.creatorRecipe(), c.anim) || { sheet: null, warnings: [], used: [] };
            c.composed = { anim: c.anim, sheet: out.sheet, warnings: out.warnings, used: out.used };
        }
        return c.composed;
    },

    // The artists of the character as drawn now: [{ file, part, authors, licences, safeToEncrypt }]. Worked out
    // once per change (creatorChanged clears it), from the stage's walk when it shows the whole character.
    creatorCredits() {
        const c = this._creator;
        if (!c) return [];
        if (!c.credits) {
            const walk = c.composed && c.composed.anim === 'walk' && c.showBody && c.composed.used ? c.composed : null;
            c.credits = this.creatorKit().credits(this, c.state, c.addons, walk);
        }
        return c.credits;
    },

    // ---- Drawing ----

    drawCreatorFrame() {
        const c = this._creator;
        const canvas = typeof document !== 'undefined' ? document.getElementById('dd-cr-canvas') : null;
        const ctx = canvas && canvas.getContext ? canvas.getContext('2d') : null;
        if (!c || !ctx || typeof ctx.createImageData !== 'function') return false;
        const K = this.creatorKit(), C = K.compose;
        const composed = this.creatorComposed();
        const F = (composed.sheet && composed.sheet.frame) || C.frame;
        this.fitCreatorCanvas(canvas, F);
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        if (!composed.sheet) return false;
        const shown = K.stageFrames(c.anim);
        const frame = shown.sequence ? shown.sequence[c.frame % shown.sequence.length] : shown.first + (c.frame % Math.max(1, shown.count));
        const rect = C.frameRect(c.anim, c.dir, frame, F);
        if (rect.x + rect.w > composed.sheet.width || rect.y + rect.h > composed.sheet.height) return false;
        const img = ctx.createImageData(rect.w, rect.h);
        for (let y = 0; y < rect.h; y++) {
            const from = ((rect.y + y) * composed.sheet.width + rect.x) * 4;
            img.data.set(composed.sheet.data.subarray(from, from + rect.w * 4), y * rect.w * 4);
        }
        if (!this._creatorScratch || this._creatorScratch.width !== F) { this._creatorScratch = document.createElement('canvas'); this._creatorScratch.width = F; this._creatorScratch.height = F; }
        this._creatorScratch.getContext('2d').putImageData(img, 0, 0);
        ctx.imageSmoothingEnabled = false;
        ctx.drawImage(this._creatorScratch, 0, 0, rect.w, rect.h, 0, 0, canvas.width, canvas.height);
        return true;
    },

    // The stage's canvas for frames of F pixels, drawn the kit's whole number of times (LPC 4, or 3 in a small
    // window; its CSS size). With oversize weapon art the canvas grows around the same body (same size, same
    // place) and the swing spills over the stage; it lets clicks through.
    fitCreatorCanvas(canvas, F) {
        const K = this.creatorKit(), narrow = Boolean(this._creator && this._creator.narrow);
        if (K.stageScaleFor) {
            // Sheets of several sizes (walking 48, battler 64, face 144), each drawn whole at its own scale.
            const k = K.stageScaleFor(F, false), s = K.stageScaleFor(F, narrow), size = s * F, css = narrow ? 192 : 256;
            if (canvas.width === k * F && canvas.height === k * F && canvas._ddSize === size) return;
            canvas.width = canvas.height = k * F;
            canvas._ddSize = size;
            if (!canvas.style) return;
            canvas.style.width = canvas.style.height = size === css ? '' : size + 'px';
            canvas.style.margin = '';
            canvas.style.pointerEvents = size > css ? 'none' : '';
            return;
        }
        const body = K.compose.frame, k = K.stageScale || 4;
        if (canvas.width === k * F && canvas.height === k * F) return;
        const s = narrow ? (K.narrowScale || 3) : k;
        const css = this._creator && this._creator.narrow ? 192 : 256;
        const size = s * F, spill = (size - s * body) / 2;
        canvas.width = canvas.height = k * F;
        if (!canvas.style) return;
        canvas.style.width = canvas.style.height = size === css ? '' : size + 'px';
        canvas.style.margin = F === body ? '' : `0 ${-spill}px ${-spill}px`;
        canvas.style.pointerEvents = F === body ? '' : 'none';
    },

    startCreatorLoop() {
        this.stopCreatorLoop();
        if (typeof setInterval === 'undefined') return;
        let last = Date.now(), acc = 0;
        this._creatorTimer = setInterval(() => {
            const c = this._creator;
            if (!c || !this.creatorOpen()) { this.stopCreatorLoop(); return; }
            this.pollCreatorPad();
            const now = Date.now();
            acc += now - last;
            last = now;
            const still = DocsDoodads.Ui.lessMotion && DocsDoodads.Ui.lessMotion();
            const step = 1000 / (this.creatorKit().fps(this)[c.anim] || 8);
            if (!still && acc >= step) { c.frame += Math.floor(acc / step); acc %= step; this.drawCreatorFrame(); }
            if (still) acc = 0;
        }, 33);
    },

    stopCreatorLoop() {
        if (this._creatorTimer) clearInterval(this._creatorTimer);
        this._creatorTimer = null;
    },

    renderCreator() {
        const D = DocsDoodads, U = D.Ui, K = this.creatorKit(), S = K.slots, c = this._creator;
        if (!c || typeof document === 'undefined') return null;
        const index = this.creatorIndex();
        let root = document.getElementById('dd-creator');
        if (!root) {
            root = document.createElement('div');
            root.id = 'dd-creator';
            root.setAttribute && root.setAttribute('role', 'dialog');
            root.setAttribute && root.setAttribute('aria-label', 'Character Creator');
            document.body.appendChild(root);
        }
        const summary = K.safeSwitch ? D.Lpc.summary(index, this.lpcSafeOnly()) : null;
        // A small window (MZ's own 816 x 624) shows one card at a time beside a smaller stage.
        const narrow = this.creatorNarrow();
        c.narrow = narrow;
        // The window is rebuilt: the focus goes back to the control with the same id afterwards.
        const active = document.activeElement;
        const keepFocus = active && active.id && root.contains && root.contains(active) ? { id: active.id, start: active.selectionStart, end: active.selectionEnd } : null;
        const rowHtml = row => {
            const v = this.creatorRowView(row);
            const here = c.cursor.card === row.card && this.creatorRows(row.card)[c.cursor.row] && this.creatorRows(row.card)[c.cursor.row].key === row.key;
            const id = 'dd-cr-' + row.key;
            const locked = this.creatorLocked(row.key);
            const lock = `<button type="button" class="dd-cr-lock${locked ? ' dd-cr-locked' : ''}" id="${id}-lock" aria-pressed="${locked}" aria-label="Lock ${escapeHtml(row.label)}" title="${row.key === '_body' ? 'Lock the body type: Shift+X keeps it (L)' : 'Lock: the dice leave it as it is (L)'}">${U.icon('lock', 1)}</button>`;
            const leadLabel = v.link ? (S.slot(v.link.lead) || { label: v.link.lead }).label.toLowerCase() : '';
            const chain = !v.link ? '' : `<button type="button" class="dd-cr-link${v.link.linked ? ' dd-cr-linked' : ''}" id="${id}-link" aria-pressed="${v.link.linked}" aria-label="${escapeHtml(row.label + ' takes the ' + leadLabel + ' colour')}" title="${escapeHtml(v.link.linked ? 'Takes the ' + leadLabel + ' colour. Click (or K) for a colour of its own' : 'Its own colour. Click (or K) to take the ' + leadLabel + ' colour again')}"${v.link.linked && v.link.colour ? ` style="background: ${escapeHtml(v.link.colour)};"` : ''}><svg viewBox="0 0 16 16" width="12" height="12" aria-hidden="true"><rect x="1.5" y="5" width="8" height="6" rx="3" fill="none" stroke="currentColor" stroke-width="2"/><rect x="6.5" y="5" width="8" height="6" rx="3" fill="none" stroke="currentColor" stroke-width="2"/></svg></button>`;
            return `<div class="dd-cr-row${here ? ' dd-cr-cursor' : ''}${v.off ? ' dd-cr-off' : ''}" id="${id}-row" data-row="${escapeHtml(row.key)}">
                ${lock}
                <span class="dd-cr-label">${escapeHtml(row.label)}</span>
                <button type="button" class="dd-cr-arrow" id="${id}-prev" aria-label="Previous ${escapeHtml(row.label)}"${v.off ? ' disabled' : ''}>◀</button>
                ${row.key === '_body' || v.off ? `<div class="dd-cr-value" title="${escapeHtml(v.value + (v.count ? ' (' + v.count + ' to choose from)' : ''))}"><span>${escapeHtml(v.value)}</span></div>`
                    : `<button type="button" class="dd-cr-value" id="${id}-value" aria-haspopup="listbox" aria-label="${escapeHtml(row.label + ': ' + v.value + '. See all ' + v.count)}" title="${escapeHtml(v.value + ' (click to see all ' + v.count + ')')}"><span>${escapeHtml(v.value)}</span></button>`}
                <button type="button" class="dd-cr-arrow" id="${id}-next" aria-label="Next ${escapeHtml(row.label)}"${v.off ? ' disabled' : ''}>▶</button>
                <span class="dd-cr-swcell">${v.channel >= 0 ? `<button type="button" class="dd-cr-swatch" id="${id}-colour" style="background: ${escapeHtml(v.colour)};" aria-label="${escapeHtml(v.channelLabel + ' colour: ' + (v.colourName ? v.colourName.replace(/_/g, ' ') : 'as drawn'))}" title="${escapeHtml((v.usable.length > 1 ? v.channelLabel + ': ' : '') + (v.colourName ? v.colourName.replace(/_/g, ' ') : 'as drawn'))} (click for all colours${v.usable.length > 1 ? '; C for the next' : ''})">${v.usable.length > 1 ? `<span class="dd-cr-chn">${v.usable.indexOf(v.channel) + 1}</span>` : ''}</button>${chain}` : chain || '<span></span>'}</span>
            </div>`;
        };
        // Where the safe-to-encrypt switch hides parts from the tab in view, a line says so, with a way to see them.
        const moreHtml = cardKey => {
            if (!this.creatorSafeOnly()) return '';
            const hidden = S.hiddenBySafeOnly(index, this.creatorRows(cardKey).filter(r => r.key !== '_body'), c.state.body);
            if (!hidden) return '';
            return `<div class="dd-cr-more" id="dd-cr-more-${cardKey}"><span>${hidden} more part${hidden === 1 ? '' : 's'} here ${hidden === 1 ? "isn't" : "aren't"} safe to encrypt.</span><button type="button" id="dd-cr-showall-${cardKey}" title="Turn off &quot;Only art safe to encrypt&quot; (at the top) to choose from every part">Show all parts</button></div>`;
        };
        const cardHtml = cardKey => {
            const card = S.cards.find(x => x.key === cardKey);
            return `<div class="dd-cr-card${c.cursor.card === cardKey ? ' dd-cr-here' : ''}${narrow && c.cursor.card !== cardKey ? ' dd-cr-hidden' : ''}" id="dd-cr-card-${cardKey}" aria-label="${escapeHtml(card.label)}">
                <div class="dd-cr-switch">${S.cards.map(k => `<button type="button" id="dd-cr-switch-${cardKey}-${k.key}" aria-pressed="${k.key === cardKey}">${escapeHtml(k.key === 'body' ? 'Body & face' : 'Outfit')}</button>`).join('')}</div>
                <div class="dd-cr-tabs" role="tablist">${card.tabs.map((t, i) => `<button type="button" role="tab" class="dd-cr-tab" id="dd-cr-tab-${cardKey}-${i}" aria-selected="${c.tabs[cardKey] === i}">${escapeHtml(t.label)}</button>`).join('')}</div>
                <div class="dd-cr-rows">${this.creatorRows(cardKey).map(rowHtml).join('')}</div>
                ${moreHtml(cardKey)}
            </div>`;
        };
        const composed = this.creatorComposed();
        const missingAnim = composed.warnings.filter(w => / has no /.test(w)).length;
        const credits = this.creatorCredits();
        const artists = new Set(credits.flatMap(f => f.authors)).size;
        const unsafe = credits.filter(f => !f.safeToEncrypt).length;
        root.innerHTML = `<div class="dd-cr${narrow ? ' dd-cr-narrow' : ''}">
            <div class="dd-cr-top">
                <div class="dd-cr-title" data-dd-help="character-creators-and-my-parts">${U.icon('person', narrow ? 1 : 2)} ${escapeHtml(K.title)}</div>
                ${this.creatorSwitcherHtml()}
                <div class="dd-cr-lib">${K.libraryLine(this, index, this.creatorSafeOnly())}</div>
                <div class="dd-cr-grow"></div>
                ${K.safeSwitch ? `<label class="dd-cr-chip" title="${this.lpcSafeOnly() ? `On: only parts offered under CC0 or OGA-BY (${summary.safe} of ${summary.parts}), which may be in a game deployed with &quot;Encrypt image files&quot;. Untick to choose from every part.` : `Off: every part (${summary.parts}). A character with CC-BY or CC-BY-SA art can't be in a game deployed with &quot;Encrypt image files&quot;; the export and Problems say which.`}"><input type="checkbox" id="dd-cr-safe" ${this.lpcSafeOnly() ? 'checked' : ''} /> Only art safe to encrypt${this.lpcSafeOnly() ? ` · ${summary.safe} of ${summary.parts}` : ''}</label>` : ''}
                <button type="button" class="dd-cr-close" id="dd-cr-close" aria-label="Close the creator" title="Close (Esc)">✕</button>
            </div>
            <div class="dd-cr-main">
                ${cardHtml('body')}
                ${narrow ? cardHtml('outfit') : ''}
                <div class="dd-cr-stagecol">
                    <div class="dd-cr-stage">
                        <button type="button" class="dd-cr-dice" id="dd-cr-dice-body" style="left: 12px;" aria-label="Shuffle the body" title="Shuffle the body and face (X)">⚄</button>
                        <input class="dd-cr-name" id="dd-cr-name" type="text" value="${escapeHtml(c.name)}" placeholder="Name your character" aria-label="Character name" />
                        <button type="button" class="dd-cr-dice" id="dd-cr-dice-outfit" style="right: 12px;" aria-label="Shuffle the outfit" title="Shuffle the outfit (Y)">⚅</button>
                        <div class="dd-cr-figure">
                            ${c.shadow ? `<div class="dd-cr-shadow"${K.feetGap ? ` style="bottom: ${Math.max(0, K.feetGap * (narrow ? K.narrowScale : K.stageScale) - 8)}px;"` : ''}></div>` : ''}
                            <canvas class="dd-cr-canvas" id="dd-cr-canvas" width="256" height="256" role="img" aria-label="${escapeHtml((c.name || 'The character') + ', ' + c.anim + ', facing ' + c.dir)}"></canvas>
                        </div>
                        <div class="dd-cr-turn">
                            <button type="button" id="dd-cr-turn-left" aria-label="Turn left" title="Turn left">↺</button>
                            <span>Facing ${escapeHtml(c.dir)}</span>
                            <button type="button" id="dd-cr-turn-right" aria-label="Turn right" title="Turn right">↻</button>
                        </div>
                    </div>
                    <div class="dd-cr-anims">${K.animations(this).map(([key, label]) => `<button type="button" class="dd-cr-anim" id="dd-cr-anim-${key}" aria-pressed="${c.anim === key}">${escapeHtml(label)}</button>`).join('')}</div>
                    <div class="dd-cr-toggles">
                        <label><input type="checkbox" id="dd-cr-showbody" ${c.showBody ? 'checked' : ''} /> Show body</label>
                        ${K.addons ? `<label><input type="checkbox" id="dd-cr-addons" ${c.addons ? 'checked' : ''} /> Body add-ons</label>` : ''}
                        <label><input type="checkbox" id="dd-cr-shadow" ${c.shadow ? 'checked' : ''} /> Cast shadow</label>
                    </div>
                    <div class="dd-cr-warn" id="dd-cr-warn">${missingAnim ? escapeHtml(`${missingAnim} part${missingAnim === 1 ? ' has' : 's have'} no ${c.anim}: ` + composed.warnings.filter(w => / has no /.test(w)).map(w => w.split(' has no ')[0]).join(', ')) : ''}</div>
                </div>
                ${narrow ? '' : cardHtml('outfit')}
            </div>
            <div class="dd-cr-bottom">
                <button type="button" class="dd-cr-btn" id="dd-cr-load">Load</button>
                <button type="button" class="dd-cr-btn" id="dd-cr-save">Save</button>
                <button type="button" class="dd-cr-btn" id="dd-cr-credits">Credits · ${artists} artist${artists === 1 ? '' : 's'}${unsafe ? ' · ' + unsafe + ' not safe to encrypt' : ''}</button>
                <div class="dd-cr-grow dd-cr-keys" style="font-size: 12px; font-weight: 700; color: #7a6b8f; text-align: right;">↑↓ pick · ←→ change · Enter see all · Shift colour · C channel · L lock · Q/E tabs · [ ] side · X/Y dice · Ctrl+Z undo</div>
                ${narrow ? '<div class="dd-cr-grow"></div>' : ''}
                <button type="button" class="dd-cr-export" id="dd-cr-export" title="Make MZ character sheets and a face from this character">Export to RPG Maker</button>
            </div>
            ${c.pop ? this.creatorPopHtml() : ''}
        </div>`;
        // The focus goes back first, so a popover that opens with the focus in it (the grid's search box)
        // keeps it.
        if (keepFocus) {
            const el = document.getElementById(keepFocus.id);
            if (el && el.focus) {
                el.focus();
                if (typeof keepFocus.start === 'number' && typeof el.setSelectionRange === 'function') { try { el.setSelectionRange(keepFocus.start, keepFocus.end); } catch (e) {} }
            }
        }
        this.bindCreator();
        this.drawCreatorFrame();
        // The cursor row stays in view (a long tab in a small window scrolls).
        const rows = this.creatorRows(c.cursor.card), cursorRow = rows[Math.min(c.cursor.row, rows.length - 1)];
        const rowEl = cursorRow ? document.getElementById('dd-cr-' + cursorRow.key + '-row') : null;
        if (rowEl && typeof rowEl.scrollIntoView === 'function') rowEl.scrollIntoView({ block: 'nearest' });
        return root;
    },

    // MZ's own window (816 x 624) and others under 1120 wide show one card at a time.
    creatorNarrow() {
        return typeof window !== 'undefined' && window.innerWidth ? window.innerWidth < 1120 : false;
    },

    creatorPopHtml() {
        const K = this.creatorKit(), S = K.slots, E = K.exporter, c = this._creator, index = this.creatorIndex();
        const pop = c.pop;
        if (pop.kind === 'grid') return this.creatorGridHtml();
        if (pop.kind === 'palette') {
            const view = this.creatorRowView(Object.assign({ key: pop.row }, S.slot(pop.row)));
            const ch = pop.channel !== undefined ? pop.channel : view.channel;
            const names = S.colours(index, view.part, ch);
            const current = this.creatorColourOf(pop.row, ch);
            const label = n => (n ? n.replace(/_/g, ' ') : 'As drawn');
            const tabs = view.channels.length > 1 ? `<div style="display: flex; flex-wrap: wrap; gap: 4px; margin-bottom: 6px;">${view.channels.map((x, i) => `<button type="button" class="dd-cr-anim" id="dd-cr-palch-${i}" aria-pressed="${i === ch}">${escapeHtml(x.label)}</button>`).join('')}</div>` : '';
            return `<div class="dd-cr-pop" id="dd-cr-pop" style="left: ${pop.x}px; top: ${pop.y}px;" role="listbox" aria-label="Colours">
                <div style="font-weight: 900; font-size: 13px; margin-bottom: 6px;">${escapeHtml(view.channels.length ? view.channels[ch].label : S.slot(pop.row).label)} colour</div>
                ${tabs}
                <div class="dd-cr-palette">${names.map((n, i) => `<button type="button" id="dd-cr-pal-${i}" aria-pressed="${n === current}" style="background: ${escapeHtml(S.swatch(index, view.part, n, ch))};" title="${escapeHtml(label(n))}" aria-label="${escapeHtml(label(n))}"></button>`).join('')}</div>
            </div>`;
        }
        if (pop.kind === 'load') {
            const saved = S.validSaved(this.readCreatorSaved()).characters;
            return `<div class="dd-cr-pop" id="dd-cr-pop" style="left: 22px; bottom: 70px;">
                <div style="font-weight: 900; font-size: 13px; margin-bottom: 6px;">Saved characters</div>
                <div class="dd-cr-list" style="flex-direction: row; min-width: 0; margin-bottom: 6px;"><button type="button" id="dd-cr-recipe-out" title="This character in a file of its own, to keep anywhere or give to someone">Export recipe...</button><button type="button" id="dd-cr-recipe-in" title="A character from a recipe file (made by this creator)">Import recipe...</button></div>
                <div class="dd-cr-list">${saved.length ? saved.map((s, i) => `<div class="dd-cr-item"><span>${escapeHtml(s.name)}</span>
                    <button type="button" id="dd-cr-load-${i}">Load</button><button type="button" id="dd-cr-del-${i}" aria-label="Delete ${escapeHtml(s.name)}">Delete</button></div>`).join('')
                    : '<div style="color: #7a6b8f;">None saved yet. Save keeps the character in data/DocsDoodadsCharacters.json.</div>'}</div>
            </div>`;
        }
        if (pop.kind === 'export') {
            const o = c.exportOptions || (c.exportOptions = K.exportDefaults(this));
            const N = E.names(c.name);
            const files = K.exportFiles(this, c.name, o, c.state);
            const unsafe = this.creatorCredits().filter(f => !f.safeToEncrypt).length;
            const tick = (id, on, label, note) => `<label style="display: flex; align-items: flex-start; gap: 6px; margin-bottom: 6px;"><input type="checkbox" id="${id}" ${on ? 'checked' : ''} style="flex: none; width: 16px; height: 16px; accent-color: #19b6a4;" /><span><b>${escapeHtml(label)}</b><br><span style="color: #7a6b8f;">${note}</span></span></label>`;
            const done = c.exported;
            return `<div class="dd-cr-pop" id="dd-cr-pop" style="right: 22px; bottom: 70px; width: 380px; font-size: 12px;">
                <div style="font-weight: 900; font-size: 14px; margin-bottom: 8px;">Export ${escapeHtml(E.cleanName(c.name) || 'your character')} to RPG Maker</div>
                ${c.name.trim() ? '' : '<div style="color: #c8472c; font-weight: 800; margin-bottom: 6px;">Name the character first (above the stage).</div>'}
                ${(K.exportTicks ? K.exportTicks(N) : [
                    ['classic', 'Classic walker', `${escapeHtml(N.classic)}.png: MZ's 3-frame walk. Works with or without this plugin.`],
                    ['smooth', 'Smooth walker, idle and run', `${escapeHtml(N.smooth)}.png and its _idle and _run sheets: every walk frame, breathing when still, running when dashing.`],
                    ['battler', 'Side-view battler', `img/sv_actors/${escapeHtml(N.face)}.png: walk, wait, chant, guard, damage, swing, thrust, missile, spell, victory, dead and the rest.`]
                ]).map(([key, label, note]) => tick('dd-cr-ex-' + key, o[key], label, note)).join('')}
                ${E.actions.length ? `<div style="margin: 0 0 6px 22px;"><b>Actions</b> <span style="color: #7a6b8f;">(for Play Character Action)</span><div style="display: flex; flex-wrap: wrap; gap: 4px; margin-top: 4px;">${E.actions.map(([anim]) => `<button type="button" class="dd-cr-anim" id="dd-cr-ex-act-${anim}" aria-pressed="${(o.actions || []).includes(anim)}" title="${escapeHtml(E.actionName(c.name, anim))}.png">${escapeHtml(E.actionLabel(anim))}</button>`).join('')}</div></div>` : ''}
                ${tick('dd-cr-ex-face', o.face, 'Face', `img/faces/${escapeHtml(N.face)}.png, in the slot picked below (the other faces in the sheet are kept).`)}
                ${o.face ? this.creatorFaceSlotsHtml(c.name, o.faceSlot || 0) : ''}
                ${(K.exportExtraTicks ? K.exportExtraTicks() : []).map(([key, label, note]) => tick('dd-cr-ex-' + key, o[key], label, note)).join('')}
                ${K.parts ? tick('dd-cr-ex-parts', o.parts, 'Outfit as Visual Equipment parts', `The character's sheets get the body and face only; each piece it wears becomes part sheets in the same layouts, with the notetag to put on a weapon or armour, so changing equipment changes what it wears.`) : ''}
                ${unsafe ? `<div style="background: #fff1c2; border-radius: 12px; padding: 6px 8px; margin-bottom: 6px; line-height: 1.4;">${unsafe} artwork${unsafe === 1 ? ' is' : 's are'} not safe to encrypt: deploy without "Encrypt image files", or change ${unsafe === 1 ? 'it' : 'them'}.</div>` : ''}
                <div style="color: #7a6b8f; margin-bottom: 8px; line-height: 1.4;">${K.exportNote()}</div>
                <div style="display: flex; gap: 8px; align-items: center;">
                    <button type="button" class="dd-cr-export" id="dd-cr-ex-go" style="font-size: 15px; padding: 8px 20px;"${!c.name.trim() || !files.length ? ' disabled' : ''}>Export ${files.length} file${files.length === 1 ? '' : 's'}</button>
                    ${done ? `<button type="button" class="dd-cr-btn" id="dd-cr-ex-try" style="font-size: 13px; padding: 6px 14px;" title="Show it on the player now (this playtest only)">Try on the player</button>` : ''}
                </div>
                ${done ? `<div id="dd-cr-ex-done" style="margin-top: 8px; color: #0f6f64; font-weight: 800; line-height: 1.4;">Wrote ${done.files.length} file${done.files.length === 1 ? '' : 's'}.${done.warnings.length ? ` <span style="color: #9a6a00;">${escapeHtml(done.warnings.slice(0, 2).join(' '))}</span>` : ''}${done.oversize && done.oversize.length && E.oversizeNote ? `<div id="dd-cr-ex-big" style="font-weight: 700; color: #5b4c70;">${escapeHtml(E.oversizeNote(done.oversize))}</div>` : ''}</div>` : ''}
                ${done && done.parts && done.parts.length ? `<div style="margin-top: 8px; max-height: 210px; overflow-y: auto; display: flex; flex-direction: column; gap: 6px;">${done.parts.map((p, i) => `
                    <div style="background: #f6efe0; border-radius: 12px; padding: 6px 8px;">
                        <b>${escapeHtml(p.label)}: ${escapeHtml(p.name)}</b>
                        <pre id="dd-cr-tag-${i}" style="margin: 4px 0; white-space: pre-wrap; word-break: break-all; font-size: 10px; background: #fffaf0; border-radius: 8px; padding: 4px 6px;">${escapeHtml(p.notetag)}</pre>
                        <div style="display: flex; gap: 4px; align-items: center;">
                            <button type="button" class="dd-cr-anim" id="dd-cr-tag-copy-${i}">Copy</button>
                            <select id="dd-cr-tag-item-${i}" style="flex: 1; min-width: 0; font-size: 11px;"><option value="">Put it on...</option>${this.lpcEquipItems().map(it => `<option value="${it.kind}${it.id}">${(this.lpcItemKinds[it.kind] || [])[2] || ''} ${it.id}: ${escapeHtml(it.name)}${it.kind === 'h' ? ' (always worn)' : ''}</option>`).join('')}</select>
                            <button type="button" class="dd-cr-anim" id="dd-cr-tag-add-${i}">Add</button>
                        </div>
                    </div>`).join('')}</div>` : ''}
            </div>`;
        }
        if (pop.kind === 'credits') {
            const files = this.creatorCredits();
            return `<div class="dd-cr-pop dd-cr-credits" id="dd-cr-pop" style="left: 140px; bottom: 70px;">
                <div style="font-weight: 900; font-size: 13px; margin-bottom: 6px;">Who made this art</div>
                ${files.map(f => `<div style="margin-bottom: 6px;"><b>${escapeHtml(f.part || f.file)}</b>${f.safeToEncrypt ? '' : ' <span style="color: #c8472c; font-weight: 900;">(not safe to encrypt)</span>'}<br>
                    by ${escapeHtml(f.authors.join(', ') || 'unknown')}<br><span style="color: #7a6b8f;">${escapeHtml(DocsDoodads.Lpc.preferredLicence(f.licences) || 'no licence found')}</span></div>`).join('')}
                <div style="color: #7a6b8f;">${K.creditsNote()}</div>
            </div>`;
        }
        return '';
    },

    bindCreator() {
        const K = this.creatorKit(), S = K.slots, E = K.exporter, c = this._creator;
        const on = (id, fn, ev = 'onclick') => { const el = document.getElementById(id); if (el) el[ev] = fn; return el; };
        on('dd-cr-close', () => this.closeCreator());
        on('dd-cr-kit', e => this.creatorSwitchKit(String(e.target.value || '')), 'onchange');
        for (const cardKey of ['body', 'outfit']) {
            S.cards.find(x => x.key === cardKey).tabs.forEach((t, i) => on(`dd-cr-tab-${cardKey}-${i}`, () => this.creatorTab(cardKey, i)));
            this.creatorRows(cardKey).forEach((row, i) => {
                const id = 'dd-cr-' + row.key;
                on(id + '-prev', () => { c.cursor = { card: cardKey, row: i }; this.creatorStep(row.key, -1); });
                on(id + '-next', () => { c.cursor = { card: cardKey, row: i }; this.creatorStep(row.key, 1); });
                on(id + '-value', () => { c.cursor = { card: cardKey, row: i }; this.creatorOpenGrid(row.key); });
                on(id + '-lock', () => { c.cursor = { card: cardKey, row: i }; this.creatorToggleLock(row.key); });
                on(id + '-link', () => { c.cursor = { card: cardKey, row: i }; this.creatorToggleLink(row.key); });
                const sw = on(id + '-colour', e => { c.cursor = { card: cardKey, row: i }; this.creatorOpenPalette(row.key, e); });
                if (sw) sw.oncontextmenu = e => { if (e && e.preventDefault) e.preventDefault(); this.creatorColour(row.key, -1); };
            });
        }
        for (const a of ['body', 'outfit']) for (const b of ['body', 'outfit']) on(`dd-cr-switch-${a}-${b}`, () => { if (c.cursor.card !== b) this.creatorCommand('card'); });
        on('dd-cr-dice-body', () => this.creatorShuffle('body'));
        on('dd-cr-dice-outfit', () => this.creatorShuffle('outfit'));
        on('dd-cr-turn-left', () => this.creatorTurn(-1));
        on('dd-cr-turn-right', () => this.creatorTurn(1));
        K.animations(this).forEach(([key, label]) => on('dd-cr-anim-' + key, () => { c.anim = key; c.frame = 0; DocsDoodads.Ui.sound('cursor'); this.renderCreator(); this.creatorSay(label); }));
        on('dd-cr-showbody', e => { c.showBody = Boolean(e.target.checked); this.creatorChanged(); }, 'onchange');
        on('dd-cr-addons', e => { c.addons = Boolean(e.target.checked); this.creatorChanged(); }, 'onchange');
        on('dd-cr-shadow', e => { c.shadow = Boolean(e.target.checked); this.renderCreator(); }, 'onchange');
        on('dd-cr-safe', e => { this.setLpcSafeOnly(Boolean(e.target.checked)); this.creatorChanged(); }, 'onchange');
        for (const card of S.cards) on('dd-cr-showall-' + card.key, () => this.creatorShowAllParts());
        on('dd-cr-name', e => { c.name = String(e.target.value || ''); }, 'oninput');
        on('dd-cr-save', () => this.creatorSave());
        on('dd-cr-load', () => { c.pop = c.pop && c.pop.kind === 'load' ? null : { kind: 'load' }; this.renderCreator(); });
        on('dd-cr-credits', () => { c.pop = c.pop && c.pop.kind === 'credits' ? null : { kind: 'credits' }; this.renderCreator(); });
        on('dd-cr-export', () => { c.pop = c.pop && c.pop.kind === 'export' ? null : { kind: 'export' }; c.exported = null; this.renderCreator(); });
        if (c.pop && c.pop.kind === 'export') {
            const o = c.exportOptions;
            E.actions.forEach(([anim]) => on('dd-cr-ex-act-' + anim, () => {
                const list = new Set(o.actions || []);
                if (list.has(anim)) list.delete(anim); else list.add(anim);
                o.actions = E.actions.map(a => a[0]).filter(a => list.has(a));
                this.renderCreator();
            }));
            ((c.exported && c.exported.parts) || []).forEach((p, i) => {
                on('dd-cr-tag-copy-' + i, () => {
                    try { if (typeof nw !== 'undefined' && nw.Clipboard) nw.Clipboard.get().set(p.notetag, 'text'); else if (navigator.clipboard) navigator.clipboard.writeText(p.notetag); } catch (e) {}
                    this.showToast('Copied the notetag for ' + p.name + '.', 'success');
                });
                on('dd-cr-tag-add-' + i, () => {
                    const sel = document.getElementById('dd-cr-tag-item-' + i);
                    const v = sel ? String(sel.value || '') : '';
                    if (!v) { this.showToast('Pick the weapon or armour to put it on.', 'info'); return; }
                    this.addLpcNotetag(v[0], parseInt(v.slice(1), 10), p.notetag, p.slot);
                });
            });
            for (const key of ['classic', 'smooth', 'face', 'battler', 'parts', 'damage', 'stand']) on('dd-cr-ex-' + key, e => { o[key] = Boolean(e.target.checked); this.renderCreator(); }, 'onchange');
            for (let slot = 0; slot < 8; slot++) on('dd-cr-ex-slot-' + slot, () => { o.faceSlot = slot; this.renderCreator(); this.creatorSay(`Face slot ${slot + 1}`); });
            on('dd-cr-ex-go', () => this.creatorExport());
            on('dd-cr-ex-try', () => { if (c.exported) { K.tryOnPlayer(this, c.exported.names, c.exportOptions.smooth); this.closeCreator(); } });
        }
        if (c.pop && c.pop.kind === 'palette') {
            const view = this.creatorRowView(Object.assign({ key: c.pop.row }, S.slot(c.pop.row)));
            const row = c.pop.row, ch = c.pop.channel !== undefined ? c.pop.channel : view.channel;
            S.colours(this.creatorIndex(), view.part, ch).forEach((n, i) => on('dd-cr-pal-' + i, () => { c.pop = view.channels.length > 1 ? c.pop : null; this.creatorColour(row, 0, n, ch); }));
            view.channels.forEach((x, i) => on('dd-cr-palch-' + i, () => { c.pop.channel = i; c.channels = Object.assign({}, c.channels, { [row]: i }); this.renderCreator(); }));
        }
        if (c.pop && c.pop.kind === 'grid') this.bindCreatorGrid();
        if (c.pop && c.pop.kind === 'load') {
            on('dd-cr-recipe-out', () => this.creatorPickRecipeOut());
            on('dd-cr-recipe-in', () => this.creatorPickRecipeIn());
            const saved = S.validSaved(this.readCreatorSaved()).characters;
            saved.forEach((s, i) => {
                on('dd-cr-load-' + i, () => this.creatorLoad(s.name));
                on('dd-cr-del-' + i, () => this.creatorDelete(s.name));
            });
        }
        if (!this._creatorKeys && typeof window !== 'undefined' && window.addEventListener) {
            this._creatorKeys = e => this.creatorKey(e);
            window.addEventListener('keydown', this._creatorKeys, true);
        }
    },

    creatorTab(cardKey, i) {
        const c = this._creator;
        const tabs = this.creatorSlots().cards.find(x => x.key === cardKey).tabs;
        c.tabs[cardKey] = (i + tabs.length) % tabs.length;
        c.cursor = { card: cardKey, row: 0 };
        c.pop = null;
        DocsDoodads.Ui.sound('cursor');
        this.renderCreator();
        const first = this.creatorRows(cardKey)[0];
        this.creatorSay(`${tabs[c.tabs[cardKey]].label} tab` + (first ? '. ' + this.creatorDescribe(first.key) : ''));
    },

    creatorTurn(step) {
        const c = this._creator;
        const order = ['down', 'left', 'up', 'right'];
        c.dir = order[(order.indexOf(c.dir) + step + 4) % 4];
        DocsDoodads.Ui.sound('cursor');
        this.renderCreator();
        this.creatorSay('Facing ' + c.dir);
    },

    creatorOpenPalette(rowKey, e) {
        const c = this._creator;
        const target = e && e.target && e.target.getBoundingClientRect ? e.target.getBoundingClientRect() : null;
        const box = typeof document !== 'undefined' && document.querySelector ? document.querySelector('#dd-creator .dd-cr') : null;
        const origin = box && box.getBoundingClientRect ? box.getBoundingClientRect() : { left: 0, top: 0 };
        const x = target ? Math.max(10, Math.min(target.left - origin.left - 120, (box ? box.clientWidth : 1160) - 250)) : 400;
        const y = target ? Math.max(10, Math.min(target.bottom - origin.top + 6, (box ? box.clientHeight : 740) - 320)) : 120;
        c.pop = c.pop && c.pop.kind === 'palette' && c.pop.row === rowKey ? null : { kind: 'palette', row: rowKey, x: Math.round(x), y: Math.round(y) };
        this.renderCreator();
    },

    // The files an export writes (paths from the kit) as { file, note, faceSlot }: the face sheet holds eight
    // faces and only the chosen one changes, which its note says.
    creatorFileEntries(files, name, o, exporter) {
        const N = exporter.names(name), face = 'img/faces/' + N.face + '.png', slot = Math.max(0, Math.min(7, o.faceSlot || 0));
        return (files || []).map(file => (file === face && o.face
            ? { file, faceSlot: slot, note: `face ${slot + 1} of 8 in ${N.face}.png; the others are kept` }
            : { file, note: '' }));
    },

    // The eight faces of the character's face sheet as it is in the project: [{ taken, url }] (url: a small
    // picture of the face). Read again only when the file changes.
    creatorFaceSlots(name) {
        const E = DocsDoodads.LpcExport, F = E.faceSize, FS = DocsDoodads.FS;
        const file = 'img/faces/' + this.creatorKit().exporter.names(name).face + '.png';
        let stamp = '';
        try { const st = FS.fs && FS.existsSync(file) ? FS.fs.statSync(file) : null; stamp = st ? st.mtimeMs + ':' + st.size : ''; } catch (e) { stamp = ''; }
        const cached = this._creatorFaceSlots;
        if (cached && cached.file === file && cached.stamp === stamp) return cached.slots;
        const sheet = stamp ? this.readLpcPng(file) : null;
        const slots = [];
        for (let slot = 0; slot < 8; slot++) {
            const face = sheet && sheet.width === F * 4 && sheet.height === F * 2 ? this.creatorFrame(sheet, { x: (slot % 4) * F, y: Math.floor(slot / 4) * F, w: F, h: F }) : null;
            const taken = Boolean(face && this.creatorTrim(face));
            slots.push({ taken, url: taken ? this.creatorThumbUrl(face, 36) : '' });
        }
        this._creatorFaceSlots = { file, stamp, slots };
        return slots;
    },

    // The face slot picker of the export: the sheet's eight faces, the empty ones blank, the chosen one outlined.
    creatorFaceSlotsHtml(name, chosen) {
        const slots = this.creatorFaceSlots(name);
        return `<div class="dd-cr-faceslots" role="radiogroup" aria-label="Face slot">${slots.map((s, i) => `<button type="button" class="dd-cr-faceslot" id="dd-cr-ex-slot-${i}" role="radio" aria-checked="${i === chosen}" aria-label="Slot ${i + 1}${s.taken ? ' (a face is there, it will be replaced)' : ', empty'}" title="Slot ${i + 1}${s.taken ? ': replaces the face there' : ': empty'}">${s.url ? `<img src="${s.url}" alt="" />` : `<span>${i + 1}</span>`}</button>`).join('')}</div>`;
    },

    // Whether a face sheet already has a face in that slot (a sheet of another size is replaced whole).
    creatorFaceSlotTaken(file, slot) {
        const E = DocsDoodads.LpcExport, F = E.faceSize;
        const sheet = this.readLpcPng(file);
        if (!sheet) return false;
        if (sheet.width !== F * 4 || sheet.height !== F * 2) return true;
        const x0 = (slot % 4) * F, y0 = Math.floor(slot / 4) * F;
        for (let y = y0; y < y0 + F; y++) for (let x = x0; x < x0 + F; x++) if (sheet.data[(y * sheet.width + x) * 4 + 3]) return true;
        return false;
    },

    // Export, asking first when it would replace pictures already in the project (a face only when its slot
    // is taken).
    async creatorExport() {
        const c = this._creator, FS = DocsDoodads.FS;
        const K = this.creatorKit();
        const o = c.exportOptions || K.exportDefaults(this);
        const existing = K.exportFiles(this, c.name, o, c.state).filter(f => FS.existsSync(f.file) && (f.faceSlot === undefined || this.creatorFaceSlotTaken(f.file, f.faceSlot)));
        if (existing.length && !await DocsDoodads.Ui.confirm(`Replace ${existing.length} picture${existing.length === 1 ? '' : 's'} already in the project?\n${existing.map(f => f.file + (f.note ? ` (${f.note})` : '')).join('\n')}`, { title: 'Export again', ok: 'Replace' })) return null;
        const result = K.exportRun(this, c.state, Object.assign({ name: c.name, addons: c.addons }, o));
        if (result) { c.exported = result; DocsDoodads.Ui.sound('save'); }
        if (this.creatorOpen()) this.renderCreator();
        return result;
    },

    // ---- Saved characters ----

    // The saved characters of a kit's slots (the open creator's by default).
    readCreatorSaved(S = this.creatorSlots()) {
        const FS = DocsDoodads.FS;
        try { return FS.existsSync(S.charactersFile) ? FS.readJson(S.charactersFile) : null; } catch (e) { return null; }
    },

    async creatorSave() {
        const S = this.creatorSlots(), c = this._creator;
        let name = c.name.trim();
        if (!name) {
            name = await DocsDoodads.Ui.prompt('A name for this character:', '', { title: 'Save character', ok: 'Save', icon: 'person' });
            if (!name || !String(name).trim()) return false;
            c.name = String(name).trim();
        }
        const data = S.save(this.readCreatorSaved(), c.name, c.state);
        if (!DocsDoodads.FS.atomicWriteJson(S.charactersFile, data)) { this.showToast('Could not save the character.', 'error'); return false; }
        DocsDoodads.Ui.sound('save');
        this.showToast(`Saved ${c.name}.`, 'success');
        this.renderCreator();
        return true;
    },

    creatorLoad(name) {
        const S = this.creatorSlots(), c = this._creator;
        const state = S.load(this.readCreatorSaved(), name);
        if (!state) return false;
        const oldPicks = JSON.parse(JSON.stringify(state.slots || {}));
        const gone = this.creatorDropStale(state);
        this.creatorRemember();
        c.state = state;
        c.name = name;
        c.pop = null;
        if (gone.length) {
            const note = S.goneNote ? S.goneNote(oldPicks, gone) : this.creatorKit().missingNote;
            this.showToast(`Some parts aren't offered now (${gone.map(k => S.slot(k) ? S.slot(k).label : k).join(', ')}): ${note}.`, 'info');
        }
        this.creatorChanged('ok', 'Loaded ' + name);
        return true;
    },

    // A loaded character's picks the library no longer offers are dropped (so a row doesn't show a part that
    // isn't there), and a slot that must have a part takes the nearest: the kit's (MZ: the same number), or
    // the body's first choice. Returns the slots that changed.
    creatorDropStale(state) {
        const S = this.creatorSlots(), index = this.creatorIndex(), safe = this.creatorSafeOnly();
        const gone = S.missing(state, index, safe);
        if (!gone.length) return gone;
        const fresh = S.newState(index, state.body, safe);
        for (const key of gone) {
            const old = state.slots[key];
            delete state.slots[key];
            const slot = S.slot(key);
            if (!slot || !slot.required) continue;
            const near = S.nearestPart ? S.nearestPart(index, slot, state.body, old && old.id, safe) : null;
            if (near) S.setPart(state, index, key, near);
            else if (fresh.slots[key]) state.slots[key] = fresh.slots[key];
        }
        return gone;
    },

    async creatorDelete(name) {
        const S = this.creatorSlots();
        if (!await DocsDoodads.Ui.confirm(`Delete the saved character "${name}"?`, { danger: true, ok: 'Delete' })) return false;
        DocsDoodads.FS.atomicWriteJson(S.charactersFile, S.remove(this.readCreatorSaved(), name));
        this.renderCreator();
        return true;
    },

    // ---- Keyboard and gamepad ----

    // One command from a key or a button: up, down, left, right, colourLeft, colourRight, channel, grid, lock,
    // link, undo, tabPrev, tabNext, card, diceBody, diceBodyType, diceOutfit, turnLeft, turnRight, save, close.
    creatorCommand(cmd) {
        const c = this._creator;
        if (!c) return false;
        const rows = this.creatorRows(c.cursor.card);
        const row = rows[Math.min(c.cursor.row, rows.length - 1)];
        // The grid picker takes the moves, A (pick) and B (close) while it is open.
        if (c.pop && c.pop.kind === 'grid') {
            const moves = { up: [0, -1], down: [0, 1], left: [-1, 0], right: [1, 0] };
            if (moves[cmd]) { this.creatorGridMove(...moves[cmd]); return true; }
            if (cmd === 'colourRight' || cmd === 'pick') { this.creatorGridPick(); return true; }
            if (cmd === 'close') { this.creatorGridEscape(); return true; }
        }
        if (c.pop && cmd !== 'close') c.pop = null;
        switch (cmd) {
            case 'up': case 'down': {
                c.cursor.row = (c.cursor.row + (cmd === 'up' ? -1 : 1) + rows.length) % rows.length;
                DocsDoodads.Ui.sound('cursor');
                this.renderCreator();
                const now = rows[c.cursor.row];
                if (now) this.creatorSay(this.creatorDescribe(now.key));
                return true;
            }
            case 'left': case 'right': if (row && !this.creatorRowView(row).off) this.creatorStep(row.key, cmd === 'left' ? -1 : 1); return true;
            case 'colourLeft': case 'colourRight': if (row && row.key !== '_body') this.creatorColour(row.key, cmd === 'colourLeft' ? -1 : 1); return true;
            case 'channel': if (row && row.key !== '_body') this.creatorNextChannel(row.key); return true;
            case 'lock': if (row) this.creatorToggleLock(row.key); return true;
            case 'link': if (row && row.key !== '_body') this.creatorToggleLink(row.key); return true;
            case 'undo': this.creatorUndo(); return true;
            case 'diceBodyType': this.creatorShuffle('body', true); return true;
            case 'grid': if (row && row.key !== '_body') this.creatorOpenGrid(row.key); return true;
            case 'tabPrev': case 'tabNext': this.creatorTab(c.cursor.card, c.tabs[c.cursor.card] + (cmd === 'tabPrev' ? -1 : 1)); return true;
            case 'card': {
                c.cursor = { card: c.cursor.card === 'body' ? 'outfit' : 'body', row: 0 };
                DocsDoodads.Ui.sound('cursor');
                this.renderCreator();
                const card = this.creatorSlots().cards.find(x => x.key === c.cursor.card);
                this.creatorSay(card ? card.label : c.cursor.card);
                return true;
            }
            case 'diceBody': this.creatorShuffle('body'); return true;
            case 'diceOutfit': this.creatorShuffle('outfit'); return true;
            case 'turnLeft': this.creatorTurn(-1); return true;
            case 'turnRight': this.creatorTurn(1); return true;
            case 'save': this.creatorSave(); return true;
            case 'close':
                if (c.pop) { c.pop = null; this.renderCreator(); return true; }
                DocsDoodads.Ui.sound('cancel');
                this.closeCreator();
                return true;
        }
        return false;
    },

    creatorKey(e) {
        if (!this.creatorOpen() || (DocsDoodads.Ui.dialogOpen && DocsDoodads.Ui.dialogOpen())) return;
        // The grid picker's keys come first while it is open (its search box keeps the rest).
        if (this._creator && this._creator.pop && this._creator.pop.kind === 'grid' && this.creatorGridKey(e)) return;
        const typing = e.target && /^(INPUT|TEXTAREA|SELECT)$/.test(e.target.tagName || '') && e.target.type !== 'checkbox';
        let cmd = null;
        const k = e.key;
        if (k === 'Escape') cmd = 'close';
        // Tab and Shift+Tab move the focus as in any dialog, round inside the window.
        else if (k === 'Tab') { this.creatorTabKey(e); return; }
        else if (typing) return;
        else if (k === 'ArrowUp') cmd = 'up';
        else if (k === 'ArrowDown') cmd = 'down';
        else if (k === 'ArrowLeft') cmd = e.shiftKey ? 'colourLeft' : 'left';
        else if (k === 'ArrowRight') cmd = e.shiftKey ? 'colourRight' : 'right';
        else if (k === 'q' || k === 'Q') cmd = 'tabPrev';
        else if (k === 'e' || k === 'E') cmd = 'tabNext';
        else if (k === '[' || k === ']' || k === '{' || k === '}') cmd = 'card';
        else if ((k === 'c' || k === 'C') && !e.ctrlKey && !e.metaKey) cmd = 'channel';
        else if (k === 'Enter' && !(e.target && /^(BUTTON|A)$/.test(e.target.tagName || ''))) cmd = 'grid';
        else if (k === 'x' || k === 'X') cmd = e.shiftKey ? 'diceBodyType' : 'diceBody';
        else if (k === 'y' || k === 'Y') cmd = 'diceOutfit';
        else if (k === ',' || k === '<') cmd = 'turnLeft';
        else if (k === '.' || k === '>') cmd = 'turnRight';
        else if ((k === 's' || k === 'S') && (e.ctrlKey || e.metaKey)) cmd = 'save';
        else if ((k === 'z' || k === 'Z') && (e.ctrlKey || e.metaKey)) cmd = 'undo';
        else if ((k === 'l' || k === 'L') && !e.ctrlKey && !e.metaKey) cmd = 'lock';
        else if ((k === 'k' || k === 'K') && !e.ctrlKey && !e.metaKey) cmd = 'link';
        // Keys the creator doesn't use still stop here, so the map tools and the game behind it don't act.
        if (!cmd) { if (e.stopPropagation) e.stopPropagation(); return; }
        if (e.preventDefault) e.preventDefault();
        if (e.stopPropagation) e.stopPropagation();
        this.creatorCommand(cmd);
    },

    // Tab inside the window: from the last control back to the first (Shift: the other way), and in from
    // outside. The key stops at the window either way.
    creatorTabKey(e) {
        if (e.stopPropagation) e.stopPropagation();
        const root = typeof document !== 'undefined' ? document.getElementById('dd-creator') : null;
        if (!root || typeof root.querySelectorAll !== 'function') return false;
        const list = Array.from(root.querySelectorAll('button, input, select, textarea, [tabindex]'))
            .filter(el => !el.disabled && el.getAttribute && el.getAttribute('tabindex') !== '-1' && (el.offsetParent !== null || (el.getClientRects && el.getClientRects().length)));
        if (!list.length) return false;
        const active = document.activeElement, at = list.indexOf(active);
        let next = null;
        if (at < 0) next = e.shiftKey ? list[list.length - 1] : list[0];
        else if (e.shiftKey && at === 0) next = list[list.length - 1];
        else if (!e.shiftKey && at === list.length - 1) next = list[0];
        if (!next) return false; // the browser moves it
        if (e.preventDefault) e.preventDefault();
        if (next.focus) next.focus();
        return true;
    },

    // Standard gamepad buttons, pressed this time and not last time; the d-pad and left stick repeat. Buttons
    // with a second use act when let go: A (held padHold ms: the next colour channel), X (held: a new body type
    // too), Y (with a direction: lock the row, without moving), Back (with B: undo, without closing).
    padHold: 600,
    padDeferred: { 0: 'colourRight', 2: 'diceBody', 3: 'diceOutfit', 8: 'card' },
    padHeldUse: { 0: 'channel', 2: 'diceBodyType' },

    pollCreatorPad() {
        if (typeof navigator === 'undefined' || typeof navigator.getGamepads !== 'function' || (DocsDoodads.Ui.dialogOpen && DocsDoodads.Ui.dialogOpen())) return;
        let pad = null;
        try { pad = Array.from(navigator.getGamepads() || []).find(p => p && p.connected); } catch (e) { pad = null; }
        if (!pad) return;
        const down = i => Boolean(pad.buttons[i] && pad.buttons[i].pressed);
        const axis = i => (pad.axes && pad.axes[i]) || 0;
        const held = {
            up: down(12) || axis(1) < -0.6, down: down(13) || axis(1) > 0.6, left: down(14) || axis(0) < -0.6, right: down(15) || axis(0) > 0.6,
            close: down(1), tabPrev: down(4), tabNext: down(5), turnLeft: down(6), turnRight: down(7), save: down(9), grid: down(11)
        };
        const was = this._creatorPad || {};
        const now = Date.now();
        const deferred = this._creatorPadHeld || (this._creatorPadHeld = {});
        const moves = ['up', 'down', 'left', 'right'];
        // Chords: Y held with a direction locks the cursor row; Back held with B undoes.
        const skip = new Set();
        if (deferred[3]) { moves.forEach(m => skip.add(m)); if (moves.some(m => held[m] && !was[m])) { deferred[3].used = true; this.creatorCommand('lock'); } }
        if (deferred[8]) { skip.add('close'); if (held.close && !was.close) { deferred[8].used = true; this.creatorCommand('undo'); } }
        for (const [b, cmd] of Object.entries(this.padDeferred)) {
            const d = deferred[b];
            if (down(Number(b))) {
                if (!d) deferred[b] = { since: now, used: false };
                else if (!d.used && this.padHeldUse[b] && now - d.since >= this.padHold) { d.used = true; this.creatorCommand(this.padHeldUse[b]); }
            } else if (d) {
                delete deferred[b];
                if (!d.used) this.creatorCommand(cmd);
            }
        }
        const repeat = this._creatorPadRepeat || (this._creatorPadRepeat = {});
        this._creatorPad = held;
        for (const [cmd, on] of Object.entries(held)) {
            if (!on || skip.has(cmd)) { if (!on) delete repeat[cmd]; continue; }
            const moving = ['up', 'down', 'left', 'right'].includes(cmd);
            if (!was[cmd]) { repeat[cmd] = now + 380; this.creatorCommand(cmd); }
            else if (moving && now >= repeat[cmd]) { repeat[cmd] = now + 120; this.creatorCommand(cmd); }
        }
    }
});
// @editor-only
//==========================================================
// SECTION 25t: LPC EXPORTS (WRITING THE SHEETS)
//==========================================================
// The creator's Export to RPG Maker: writes the character's sheets into img/characters (and its face into
// img/faces), records the credits of every file and writes CREDITS_LPC.txt again, adds the animation set
// that plays the idle and run sheets with the smooth walker, and keeps the character under its name so it
// can be changed and exported again. Also, when ticked: action sheets for Play Character Action
// ($Name_slash[f6]...) and a side-view battler (img/sv_actors/Name.png). Layouts are in 23_lpc_export.js.
// Sheets drawn with oversize weapon art have bigger frames; the result lists them (oversize), and action
// sheets whose frames reach below the feet are noted in characterAnim.feet so the plugin stands them on their
// feet without changing their names.
Object.assign(DocsDoodads.Workspace, {
    // What to make. options: { name, classic, smooth (with idle and run), face, faceSlot, battler, actions: [anim] }
    lpcExportDefaults() {
        return { classic: true, smooth: true, face: true, faceSlot: 0, battler: true, actions: ['slash', 'thrust', 'spellcast', 'shoot', 'hurt'] };
    },

    // The files an export would write, relative to the project.
    lpcExportFiles(name, options) {
        const N = DocsDoodads.LpcExport.names(name);
        const files = [];
        if (options.classic) files.push('img/characters/' + N.classic + '.png');
        if (options.smooth) files.push('img/characters/' + N.smooth + '.png', 'img/characters/' + N.idle + '.png', 'img/characters/' + N.run + '.png');
        if (options.face) files.push('img/faces/' + N.face + '.png');
        if (options.battler) files.push('img/sv_actors/' + N.face + '.png');
        for (const anim of options.actions || []) files.push('img/characters/' + DocsDoodads.LpcExport.actionName(name, anim) + '.png');
        return files;
    },

    writeLpcPng(file, image) {
        const D = DocsDoodads, FS = D.FS;
        const zlib = require('zlib');
        FS.mkdirp(FS.path.dirname(file));
        FS.fs.writeFileSync(file, D.AsepriteSheets.encodePng(image.width, image.height, new Uint8Array(image.data.buffer, image.data.byteOffset, image.data.length), data => zlib.deflateSync(data)));
        // A playtest that already drew the old picture would keep showing it.
        if (typeof ImageManager !== 'undefined' && ImageManager._cache) {
            for (const key of Object.keys(ImageManager._cache)) if (key.endsWith(file) || key.endsWith(encodeURI(file))) delete ImageManager._cache[key];
        }
    },

    readLpcPng(file) {
        const FS = DocsDoodads.FS;
        try { return FS.existsSync(file) ? DocsDoodads.LpcCompose.decodePng(FS.fs.readFileSync(file), d => require('zlib').inflateSync(d)) : null; } catch (e) { return null; }
    },

    // Writes everything; returns { files, warnings } or null (with a message) when it can't.
    exportLpcCharacter(state, options) {
        const D = DocsDoodads, E = D.LpcExport, S = D.LpcSlots, FS = D.FS;
        if (!FS.fs || !FS.writable()) { this.showToast('Characters are exported in a playtest.', 'info'); return null; }
        const name = E.cleanName(options.name);
        if (!name) { this.showToast('Give the character a name first.', 'info'); return null; }
        const N = E.names(name);
        // With the outfit as Visual Equipment parts, the character's own sheets are the body and face only;
        // what it wears comes from its equipment.
        const own = options.parts ? { body: state.body, slots: Object.fromEntries(Object.entries(state.slots).filter(([k]) => S.slot(k) && S.slot(k).card === 'body')) } : state;
        const recipe = S.toRecipe(own, { addons: options.addons !== false });
        const walk = this.composeLpc(recipe, 'walk');
        if (!walk || !walk.sheet) { this.showToast('Nothing to export: the character has no walk.', 'error'); return null; }
        const written = [];
        const warnings = walk.warnings.slice();
        const record = (file, used) => { written.push(file); this.recordLpcImage(file, used); };
        // The sheets with bigger frames: [{ file, w, h, below }] (the size of one frame, and how far it reaches
        // below the feet).
        const oversize = [];
        const big = (file, sheet, full) => {
            const F = E.frameOf(sheet);
            if (F > E.frame) oversize.push(Object.assign({ file }, E.cellOf(F, full)));
        };
        // Action sheets reaching below the feet (and ones that no longer do).
        let feet = D.World.get('characterAnim.feet') || {};
        // Battlers grown for a big weapon: the figure's height, so battle animations aim at it.
        let bodies = D.World.get('characterAnim.svBody') || {};
        const action = (file, sheet) => {
            feet = E.feetWith(feet, file.replace(/^.*\//, '').replace(/\.png$/i, ''), E.actionBelow(sheet));
            big(file, sheet, true);
        };
        const battler = (file, sv) => {
            if (sv.oversize.length) oversize.push({ file, w: sv.cell.w, h: sv.cell.h, below: 0, motions: sv.oversize });
        };
        let parts = [];
        try {
            if (options.classic) {
                const file = 'img/characters/' + N.classic + '.png';
                this.writeLpcPng(file, E.classic(walk.sheet));
                record(file, walk.used);
                big(file, walk.sheet);
            }
            if (options.smooth) {
                const file = 'img/characters/' + N.smooth + '.png';
                this.writeLpcPng(file, E.allFrames(walk.sheet));
                record(file, walk.used);
                big(file, walk.sheet);
                for (const [anim, sheetName] of [['idle', N.idle], ['run', N.run]]) {
                    const out = this.composeLpc(recipe, anim);
                    if (!out || !out.sheet) { warnings.push(`No ${anim} sheet: the parts have no ${anim}.`); continue; }
                    const f = 'img/characters/' + sheetName + '.png';
                    this.writeLpcPng(f, E.allFrames(out.sheet));
                    record(f, out.used);
                    big(f, out.sheet);
                    warnings.push(...out.warnings.filter(w => !warnings.includes(w)));
                }
                this.addLpcAnimationSet(N);
            }
            for (const anim of options.actions || []) {
                const out = this.composeLpc(recipe, anim);
                if (!out || !out.sheet) { warnings.push(`No ${anim} action: the parts have no ${anim}.`); continue; }
                const f = 'img/characters/' + E.actionName(name, anim) + '.png';
                this.writeLpcPng(f, E.actionSheet(out.sheet, anim));
                record(f, out.used);
                action(f, out.sheet);
                warnings.push(...out.warnings.filter(w => !warnings.includes(w)));
            }
            if (options.battler) {
                const sheets = {}, used = [];
                for (const anim of E.svAnimations()) {
                    const out = this.composeLpc(recipe, anim);
                    sheets[anim] = out && out.sheet;
                    if (out) used.push(...out.used);
                }
                const sv = E.svSheet(sheets);
                const f = 'img/sv_actors/' + N.face + '.png';
                this.writeLpcPng(f, sv.sheet);
                record(f, used);
                battler(f, sv);
                bodies = E.feetWith(bodies, N.face, sv.cell.h > E.frame ? E.frame : 0);
                if (sv.fellBack.length) warnings.push(`The battler's ${sv.fellBack.join(', ')} use${sv.fellBack.length === 1 ? 's' : ''} another animation (the parts have none of their own).`);
            }
            if (options.face) {
                // The face leaves out what is held or carried.
                const faceState = { body: state.body, slots: Object.assign({}, state.slots) };
                for (const key of ['weapon', 'shield', 'back', 'ammo']) delete faceState.slots[key];
                const faceWalk = this.composeLpc(S.toRecipe(faceState, { addons: options.addons !== false }), 'walk', null, { oversize: false });
                const file = 'img/faces/' + N.face + '.png';
                this.writeLpcPng(file, E.faceSheet(this.readLpcPng(file), E.face(faceWalk.sheet), options.faceSlot || 0));
                record(file, faceWalk.used);
            }
            if (options.parts) parts = this.exportLpcParts(state, options, record, warnings, { big, action, battler });
        } catch (e) {
            this.showToast('Could not write the sheets: ' + (e.message || e), 'error');
            return null;
        }
        if (JSON.stringify(feet) !== JSON.stringify(D.World.get('characterAnim.feet') || {})) this.setWorldSetting('characterAnim.feet', feet);
        if (JSON.stringify(bodies) !== JSON.stringify(D.World.get('characterAnim.svBody') || {})) this.setWorldSetting('characterAnim.svBody', bodies);
        // Credits ship with the game; the character is kept to change and export again.
        if (written.length) this.writeLpcCreditsText();
        FS.atomicWriteJson(S.charactersFile, S.save(this.readCreatorSaved(S), name, state));
        const unsafe = D.Lpc.unsafeImages(this.lpcCredits(), f => written.includes(f)).length;
        this.showToast(`Exported ${name}: ${written.length} picture${written.length === 1 ? '' : 's'}` + (unsafe ? `; ${unsafe} can't be encrypted` : '') + '.', unsafe ? 'info' : 'success');
        return { files: written, warnings: [...new Set(warnings)], names: N, parts, oversize };
    },

    // The part sheets exportLpcParts would write, by name only (nothing drawn): a piece in front of the body
    // and one behind it where the part has layers there, each in the ticked layouts its animations allow.
    lpcPartFiles(state, options) {
        const D = DocsDoodads, E = D.LpcExport, S = D.LpcSlots;
        const index = this.lpcIndex();
        const out = [];
        if (!index || !state) return out;
        for (const slot of S.allSlots().filter(s => s.card === 'outfit')) {
            const pick = state.slots[slot.key];
            const part = pick && index.parts.find(p => p.id === pick.id);
            if (!part) continue;
            const has = anim => !part.animations.length || part.animations.includes(anim);
            for (const behind of [false, true]) {
                if (!part.layers.some(l => l.paths[state.body] && (behind ? l.z < E.bodyZ : l.z >= E.bodyZ))) continue;
                const base = E.partBase(slot.label, part.name, pick.colour, state.body, behind), N = E.names(base);
                const note = `outfit part: ${slot.label}${behind ? ' (behind)' : ''}`;
                if (options.classic) out.push({ file: 'img/characters/' + N.classic + '.png', note });
                if (options.smooth) {
                    out.push({ file: 'img/characters/' + N.smooth + '.png', note });
                    if (has('idle')) out.push({ file: 'img/characters/' + N.idle + '.png', note });
                    if (has('run')) out.push({ file: 'img/characters/' + N.run + '.png', note });
                }
                for (const anim of options.actions || []) if (has(anim)) out.push({ file: 'img/characters/' + E.actionName(base, anim) + '.png', note });
                if (options.battler) out.push({ file: 'img/sv_actors/' + N.face + '.png', note });
            }
        }
        return out;
    },

    // Each outfit piece as Visual Equipment part sheets, in the same layouts the character uses (so the
    // pieces follow its walk, idle, run, actions and battler), with the notetag that puts it on an item.
    // Layers below the body (a quiver, a cape's back) are a second piece in the same part slot. Oversize
    // weapon art gives a piece bigger frames standing on the same feet (Visual Equipment draws each layer at
    // its own frame size); a return swing is played to follow the body's own slash. note: { big, action,
    // battler } to list sheets with bigger frames.
    exportLpcParts(state, options, record, warnings, note = {}) {
        // A dry run: the files it would write, nothing drawn or written.
        if (note.dryRun) return this.lpcPartFiles(state, options);
        const D = DocsDoodads, E = D.LpcExport, S = D.LpcSlots;
        const index = this.lpcIndex();
        const out = [];
        for (const slot of S.allSlots().filter(s => s.card === 'outfit')) {
            const pick = state.slots[slot.key];
            const part = pick && index.parts.find(p => p.id === pick.id);
            if (!part) continue;
            const colours = [pick.colour || ''].concat(pick.colour2 ? [pick.colour2] : []);
            const recipe = { body: state.body, picks: [{ id: pick.id, colours, variant: pick.colour || undefined }] };
            const pieces = [], files = [];
            const write = (file, image, used, sheet, kind) => {
                this.writeLpcPng(file, image);
                record(file, used);
                files.push(file);
                if (kind === 'action' && note.action) note.action(file, sheet);
                else if (kind && note.big) note.big(file, sheet);
            };
            for (const behind of [false, true]) {
                const keep = l => (behind ? l.z < E.bodyZ : l.z >= E.bodyZ);
                const walk = this.composeLpc(recipe, 'walk', keep);
                if (!walk || !walk.sheet || !walk.used.length) continue;
                const base = E.partBase(slot.label, part.name, pick.colour, state.body, behind);
                const N = E.names(base);
                if (options.classic) write('img/characters/' + N.classic + '.png', E.classic(walk.sheet), walk.used, walk.sheet, 'sheet');
                if (options.smooth) {
                    write('img/characters/' + N.smooth + '.png', E.allFrames(walk.sheet), walk.used, walk.sheet, 'sheet');
                    for (const [anim, sheetName] of [['idle', N.idle], ['run', N.run]]) {
                        const o = this.composeLpc(recipe, anim, keep);
                        if (o && o.sheet && o.used.length) write('img/characters/' + sheetName + '.png', E.allFrames(o.sheet), o.used, o.sheet, 'sheet');
                    }
                }
                for (const anim of options.actions || []) {
                    const o = this.composeLpc(recipe, anim, keep);
                    if (o && o.sheet && o.used.length) write('img/characters/' + E.actionName(base, anim) + '.png', E.actionSheet(o.sheet, anim), o.used, o.sheet, 'action');
                }
                if (options.battler) {
                    const sheets = {}, used = [];
                    for (const anim of E.svAnimations()) {
                        const o = this.composeLpc(recipe, anim, keep);
                        sheets[anim] = o && o.used.length ? o.sheet : null;
                        if (o) used.push(...o.used);
                    }
                    const sv = E.svSheet(sheets), f = 'img/sv_actors/' + N.face + '.png';
                    write(f, sv.sheet, used);
                    if (note.battler) note.battler(f, sv);
                }
                // Visual Equipment z: below 0 is behind the body; the library's order is kept.
                const zs = part.layers.map(l => l.z).filter(z => (behind ? z < E.bodyZ : z >= E.bodyZ));
                pieces.push({ base, z: behind ? Math.min(-1, Math.min(...zs) - E.bodyZ) : Math.max(1, Math.max(...zs) - E.bodyZ) });
            }
            if (!pieces.length) { warnings.push(`${part.name} has nothing to draw for the ${state.body} body.`); continue; }
            out.push({ slot: slot.key, label: slot.label, name: part.name, files,
                notetag: E.partNotetag(slot.key, pieces, { smooth: options.smooth !== false || !options.classic, battler: Boolean(options.battler) }) });
        }
        return out;
    },

    // ---- Notetags on the database's weapons and armours ----

    // w: weapons, a: armours, h: actors (clothes always worn: an equipped item with the same part replaces them).
    lpcItemKinds: { w: ['data/Weapons.json', '$dataWeapons', 'Weapon'], a: ['data/Armors.json', '$dataArmors', 'Armour'], h: ['data/Actors.json', '$dataActors', 'Actor'] },

    lpcItemFile(kind) {
        return (this.lpcItemKinds[kind] || this.lpcItemKinds.a)[0];
    },

    lpcLiveList(kind) {
        const global = typeof window !== 'undefined' ? window : {};
        return global[(this.lpcItemKinds[kind] || this.lpcItemKinds.a)[1]] || null;
    },

    // Weapons and armours to put a part on: [{ kind, id, name }].
    lpcEquipItems() {
        const out = [];
        const add = (list, kind) => (list || []).forEach(item => { if (item && item.name) out.push({ kind, id: item.id, name: item.name }); });
        add(typeof $dataWeapons !== 'undefined' ? $dataWeapons : null, 'w');
        add(typeof $dataArmors !== 'undefined' ? $dataArmors : null, 'a');
        add(typeof $dataActors !== 'undefined' ? $dataActors : null, 'h');
        return out;
    },

    // The note with a part's notetag: an earlier LPC notetag for the same part is replaced, the rest kept.
    lpcNoteWith(note, notetag, part) {
        const mine = new RegExp('^\\s*<\\s*visual\\s*:\\s*\\$LPC [^>]*\\bpart\\s+' + String(part).replace(/[^\w]/g, '') + '\\s*(,[^>]*)?>\\s*$', 'i');
        const kept = String(note || '').split('\n').filter(line => !mine.test(line));
        while (kept.length && !kept[kept.length - 1].trim()) kept.pop();
        return kept.concat(notetag.split('\n')).join('\n');
    },

    // Writes the notetag into data/Weapons.json or data/Armors.json (after a backup, in MZ's own layout)
    // and into the running game, so it can be tried at once.
    addLpcNotetag(kind, id, notetag, part) {
        const D = DocsDoodads, FS = D.FS;
        const file = this.lpcItemFile(kind);
        if (!FS.fs || !FS.writable()) { this.showToast('Notetags are added in a playtest.', 'info'); return false; }
        let list = null;
        try { list = FS.readJson(file); } catch (e) { list = null; }
        const item = Array.isArray(list) ? list[id] : null;
        if (!item) { this.showToast(`There is no ${(this.lpcItemKinds[kind] || this.lpcItemKinds.a)[2].toLowerCase()} ${id}.`, 'error'); return false; }
        item.note = this.lpcNoteWith(item.note, notetag, part);
        try {
            FS.createTimestampedBackup(file);
            const text = '[\n' + list.map(x => JSON.stringify(x)).join(',\n') + '\n]';
            FS.fs.writeFileSync(file + '.tmp', text, 'utf8');
            FS.fs.renameSync(file + '.tmp', file);
        } catch (e) {
            this.showToast('Could not write ' + file + ': ' + (e.message || e), 'error');
            return false;
        }
        const live = this.lpcLiveList(kind);
        if (live && live[id]) {
            live[id].note = item.note;
            if (typeof DataManager !== 'undefined' && DataManager.extractMetadata) DataManager.extractMetadata(live[id]);
        }
        this.showToast(`Added to ${item.name}. If MZ's editor has this project open, reopen the project there before saving, or it will put the old note back.`, 'success');
        return true;
    },

    // The animation set for the smooth walker (replacing one for the same sheet).
    addLpcAnimationSet(N) {
        const set = DocsDoodads.LpcExport.animationSet(N);
        const sets = (DocsDoodads.World.get('characterAnim.sets') || []).filter(s => s && s.character !== set.character);
        sets.push(set);
        this.setWorldSetting('characterAnim.sets', sets);
        return set;
    },

    // Try the character on the player (this playtest only; MZ's database is not changed).
    tryLpcOnPlayer(N, smooth = true) {
        if (typeof $gamePlayer === 'undefined' || !$gamePlayer) return false;
        $gamePlayer.setImage(smooth ? N.smooth : N.classic, 0);
        return true;
    }
});
// @editor-only
//==========================================================
// SECTION 25r: LPC CHARACTER LIBRARY (CARD, SCAN, CREDITS)
//==========================================================
// More > Characters: a group per library (MZ's generator, LPC, Memao), each folded or open as last left on this
// computer. The LPC group: where the LPC library is on this computer, a scan of its parts into the editor's
// cache, whether this project uses only art that is safe to encrypt, and the credits of images made from
// it (data/DocsDoodadsCredits.json, written out as CREDITS_LPC.txt beside the game). The folder is kept per
// computer and should be outside the project: MZ's Deployment copies everything in the project folder.
// Problems (44_workspace_map_check.js) lists images that can't be encrypted and credits that need writing out.
DocsDoodads.Ui.css += `
#dd-lpc-card { position: fixed; top: 80px; left: 50%; transform: translateX(-50%); z-index: 10045; width: 440px; max-width: calc(100vw - 32px); max-height: calc(100vh - 110px); padding: 12px 14px; display: flex; flex-direction: column; gap: 8px; overflow-y: auto; font-size: 11px; }
#dd-lpc-card .dd-lpc-row { display: flex; gap: 6px; align-items: center; }
#dd-lpc-card .dd-lpc-row input[type=text] { flex: 1; min-width: 0; }
#dd-lpc-card .dd-lpc-group { font-size: 11px; font-weight: 900; color: var(--dd-muted); margin-top: 4px; }
#dd-lpc-card .dd-lpc-box { background: var(--dd-panel-2); border-radius: 12px; padding: 8px 10px; line-height: 1.5; color: var(--dd-text); }
#dd-lpc-card .dd-lpc-warn { background: var(--dd-warn-soft); border-radius: 12px; padding: 8px 10px; line-height: 1.45; color: var(--dd-text); }
#dd-lpc-card .dd-lpc-note { font-size: 10px; color: var(--dd-faint); line-height: 1.4; }
#dd-lpc-card label { display: flex; align-items: center; gap: 6px; }
#dd-lpc-card .dd-lpc-try { display: flex; align-items: center; gap: 6px; }
#dd-lpc-card #dd-lpc-preview { width: 128px; height: 128px; image-rendering: pixelated; border-radius: 16px; background: var(--dd-primary-soft); }
#dd-lpc-card .dd-lpc-try-side { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 4px; align-items: flex-start; }
#dd-lpc-card .dd-chars-group { border-top: 2px solid var(--dd-line-soft); padding-top: 6px; }
#dd-lpc-card .dd-chars-group summary { display: flex; align-items: center; gap: 8px; cursor: pointer; font-size: 12px; font-weight: 900; color: var(--dd-text); list-style: none; }
#dd-lpc-card .dd-chars-group summary::before { content: '▸'; color: var(--dd-muted); }
#dd-lpc-card .dd-chars-group[open] summary::before { content: '▾'; }
#dd-lpc-card .dd-chars-status { font-size: 10px; font-weight: 800; color: var(--dd-muted); }
#dd-lpc-card .dd-chars-body { display: flex; flex-direction: column; gap: 8px; margin-top: 6px; }
`;

Object.assign(DocsDoodads.Workspace, {
    _lpcIndex: undefined,

    lpcLibraryFolder() {
        const v = DocsDoodads.Ui.prefs().lpcLibrary;
        return typeof v === 'string' ? v : '';
    },

    setLpcLibraryFolder(folder) {
        const clean = String(folder || '').trim();
        DocsDoodads.Ui.setPref('lpcLibrary', clean || undefined);
        return clean;
    },

    lpcMineFolder() { const v = DocsDoodads.Ui.prefs().lpcMine; return typeof v === 'string' ? v : ''; },
    setLpcMineFolder(folder) { const clean = String(folder || '').trim(); DocsDoodads.Ui.setPref('lpcMine', clean || undefined); return clean; },

    lpcSafeOnly() {
        return DocsDoodads.World.get('lpc.safeOnly') !== false;
    },

    setLpcSafeOnly(on) {
        // Through the workspace, so the change is saved with the project (and can be undone).
        this.setWorldSetting('lpc.safeOnly', on ? undefined : false);
    },

    // The saved index (cached after the first read), or null.
    lpcIndex() {
        if (this._lpcIndex === undefined) {
            const D = DocsDoodads;
            let data = null;
            try { data = D.FS.existsSync(D.Lpc.indexFile) ? D.FS.readJson(D.Lpc.indexFile) : null; } catch (e) { data = null; }
            this._lpcIndex = D.Lpc.validIndex(data);
        }
        return this._lpcIndex;
    },

    // Scans the library folder into the cache. Returns the index, or null (with a message) when it can't.
    scanLpcLibrary(folder = this.lpcLibraryFolder()) {
        const D = DocsDoodads, L = D.Lpc, FS = D.FS;
        if (!FS.fs || !FS.path) return null;
        if (!folder) { this.showToast('Choose the LPC library folder first.', 'info'); return null; }
        if (!L.isLibrary(FS.fs, FS.path, folder)) {
            this.showToast('That folder has no sheet_definitions and spritesheets folders. Choose the top folder of the LPC character generator.', 'error');
            return null;
        }
        const base = L.scan(FS.fs, FS.path, FS.path.resolve(folder));
        if (!base) return null;
        const mineFolder = this.lpcMineFolder();
        let mine = null;
        if (mineFolder) {
            if (!L.isLibrary(FS.fs, FS.path, mineFolder)) { this.showToast('The LPC My parts folder needs sheet_definitions and spritesheets.', 'error'); return null; }
            mine = L.scan(FS.fs, FS.path, FS.path.resolve(mineFolder), undefined, { mine: true });
        }
        const index = mine ? L.mergeIndexes(base, mine, FS.path.basename(FS.path.resolve(mineFolder))) : base;
        if (!FS.atomicWriteJson(L.indexFile, index, 0)) { this.showToast('Could not save the library index.', 'error'); return null; }
        this._lpcIndex = index;
        this.resetCreatorImageCaches('lpc');
        const s = L.summary(index, this.lpcSafeOnly());
        this.showToast(`Found ${s.parts} character parts (${s.safe} safe to encrypt)` + (s.skipped ? `; ${s.skipped} skipped` : '') + '.', 'success');
        return index;
    },

    // The library has moved on since the scan (another commit), or isn't where the scan found it.
    lpcIndexStale(index = this.lpcIndex()) {
        const D = DocsDoodads, FS = D.FS;
        if (!index || !FS.fs) return '';
        if (!D.Lpc.isLibrary(FS.fs, FS.path, index.library)) return 'missing';
        const now = D.Lpc.libraryCommit(FS.fs, FS.path, index.library);
        return now && index.commit && now !== index.commit ? 'changed' : '';
    },

    // ---- Credits ----

    lpcCredits() {
        const D = DocsDoodads;
        let data = null;
        try { data = D.FS.existsSync(D.Lpc.creditsFile) ? D.FS.readJson(D.Lpc.creditsFile) : null; } catch (e) { data = null; }
        return D.Lpc.validCredits(data);
    },

    lpcImageExists(image) {
        return DocsDoodads.FS.existsSync(String(image));
    },

    // For the exports (phase 4): records which library folders an image was made from.
    // used: [{ part, folder }] as the compositor drew them.
    recordLpcImage(image, used) {
        const D = DocsDoodads, L = D.Lpc;
        const data = L.recordImage(this.lpcCredits(), image, L.creditsForLayers(used));
        return D.FS.atomicWriteJson(L.creditsFile, data) ? data.images[image] : null;
    },

    // CREDITS_LPC.txt's state: 'none' (nothing made), 'missing', 'old' (credits changed since) or 'ok'.
    lpcCreditsTextState(data = this.lpcCredits()) {
        const D = DocsDoodads, L = D.Lpc, FS = D.FS;
        const want = L.creditsTextFor(data, img => this.lpcImageExists(img));
        if (!Object.keys(data.images).some(img => this.lpcImageExists(img))) return 'none';
        if (!FS.existsSync(L.creditsText)) return 'missing';
        let have = '';
        try { have = String(FS.readFileSync(L.creditsText, 'utf8')); } catch (e) { return 'missing'; }
        return have.replace(/\r\n/g, '\n') === want ? 'ok' : 'old';
    },

    writeLpcCreditsText() {
        const D = DocsDoodads, L = D.Lpc, FS = D.FS;
        try {
            FS.writeFileSync(L.creditsText, L.creditsTextFor(this.lpcCredits(), img => this.lpcImageExists(img)), 'utf8');
        } catch (e) {
            this.showToast('Could not write ' + L.creditsText + ': ' + (e.message || e), 'error');
            return false;
        }
        this.showToast('Wrote ' + L.creditsText + '. It goes into the game with the other files.', 'success');
        return true;
    },

    // Project-wide entries for Problems (no map to go to).
    lpcProblems() {
        const D = DocsDoodads, L = D.Lpc;
        const data = this.lpcCredits();
        const out = L.unsafeImages(data, img => this.lpcImageExists(img)).map(u => ({
            kind: 'lpcEncrypt', global: true,
            text: `${u.image.replace(/^img\/[^/]+\//, '')}: ` + (u.uncredited ? 'uses art with no credits; find its authors and licence before shipping.'
                : `its art is only offered under ${u.licences.join(', ')}. Leave "Encrypt image files" off when deploying, or remake it with only art that is safe to encrypt.`)
        }));
        const state = this.lpcCreditsTextState(data);
        if (state === 'missing' || state === 'old') {
            out.push({ kind: 'lpcCredits', global: true,
                text: state === 'missing' ? `${L.creditsText} hasn't been written: the artists of your LPC characters must be credited in the game.` : `${L.creditsText} is out of date with the characters made since.`,
                fix: { label: 'Write It', run: () => this.writeLpcCreditsText() } });
        }
        return out;
    },

    // ---- Drawing characters from the library ----

    lpcSheetPath(file, index = this.lpcIndex()) {
        const FS = DocsDoodads.FS;
        return index && FS.path ? DocsDoodads.Lpc.filePath(FS.path, index, file) : '';
    },

    // A library image, decoded once (or null). The recoloured layers are cached by the compositor.
    lpcLoadImage(file) {
        return this.creatorRawImage('lpc', file, () => {
            const FS = DocsDoodads.FS;
            try {
                const zlib = typeof require !== 'undefined' ? require('zlib') : null;
                if (!zlib || !FS.fs) return null;
                return DocsDoodads.LpcCompose.decodePng(FS.fs.readFileSync(this.lpcSheetPath(file)), data => zlib.inflateSync(data));
            } catch (e) {
                return null;
            }
        });
    },

    lpcCache() {
        return this.creatorImageCaches('lpc').layers;
    },

    // recipe -> { sheet, warnings, used, oversize } for one animation, or null without an index. keep(layer):
    // only some layers (the pieces of a Visual Equipment part in front of or behind the body, which is drawn
    // on a sheet of its own and so plays the animation its own way). Oversize weapon art makes the sheet's
    // frames bigger (sheet.frame), unless options.oversize is false.
    composeLpc(recipe, animation = 'walk', keep, options = {}) {
        const C = DocsDoodads.LpcCompose, FS = DocsDoodads.FS;
        const index = this.lpcIndex();
        if (!index || !FS.fs) return null;
        const resolved = C.resolve(index, recipe, animation, file => FS.existsSync(this.lpcSheetPath(file, index)),
            { oversize: options.oversize !== false, separateBody: Boolean(keep) });
        if (keep) {
            resolved.layers = resolved.layers.filter(keep);
            resolved.used = resolved.layers.map(l => ({ part: l.part, folder: l.folder }));
            resolved.frame = Math.max(C.frame, ...resolved.layers.map(l => l.frame || C.frame));
        }
        const out = C.compose(resolved, index, file => this.lpcLoadImage(file), this.lpcCache());
        return { sheet: out.sheet, warnings: out.warnings, used: resolved.used, oversize: resolved.oversize };
    },

    // The card's try-out: a random character walking, turned with the arrows.
    shuffleLpcPreview() {
        const index = this.lpcIndex();
        if (!index) return null;
        const p = this._lpcPreview || { dir: 'down', frame: 0 };
        p.recipe = DocsDoodads.LpcCompose.randomRecipe(index, { safeOnly: this.lpcSafeOnly() });
        const out = this.composeLpc(p.recipe, 'walk');
        p.sheet = out && out.sheet;
        p.warnings = out ? out.warnings : [];
        this._lpcPreview = p;
        this.drawLpcPreview();
        return p;
    },

    turnLpcPreview(step) {
        const p = this._lpcPreview;
        if (!p) return;
        const order = ['down', 'left', 'up', 'right'];
        p.dir = order[(order.indexOf(p.dir) + step + 4) % 4];
        this.drawLpcPreview();
    },

    drawLpcPreview() {
        const p = this._lpcPreview;
        const canvas = typeof document !== 'undefined' ? document.getElementById('dd-lpc-preview') : null;
        const ctx = canvas && canvas.getContext ? canvas.getContext('2d') : null;
        if (!p || !p.sheet || !ctx || typeof ctx.createImageData !== 'function') return false;
        const C = DocsDoodads.LpcCompose;
        // Walking frames 1-8; frame 0 is standing.
        const rect = C.frameRect('walk', p.dir, 1 + (p.frame % 8));
        const frame = ctx.createImageData(rect.w, rect.h);
        for (let y = 0; y < rect.h; y++) {
            const from = ((rect.y + y) * p.sheet.width + rect.x) * 4;
            frame.data.set(p.sheet.data.subarray(from, from + rect.w * 4), y * rect.w * 4);
        }
        if (!this._lpcScratch) { this._lpcScratch = document.createElement('canvas'); this._lpcScratch.width = rect.w; this._lpcScratch.height = rect.h; }
        this._lpcScratch.getContext('2d').putImageData(frame, 0, 0);
        ctx.imageSmoothingEnabled = false;
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        ctx.drawImage(this._lpcScratch, 0, 0, rect.w, rect.h, 0, 0, canvas.width, canvas.height);
        return true;
    },

    // 'Male: Body Color, Human Male, Bob, Longsleeve' for the try-out.
    lpcRecipeText(recipe) {
        const index = this.lpcIndex();
        const name = id => { const p = index && index.parts.find(x => x.id === id); return p ? p.name : id; };
        const body = recipe.body.charAt(0).toUpperCase() + recipe.body.slice(1);
        return body + ': ' + recipe.picks.filter(p => p.id !== 'body/body').map(p => name(p.id)).join(', ');
    },

    startLpcPreviewTimer() {
        this.stopLpcPreviewTimer();
        const reduced = DocsDoodads.Ui.lessMotion && DocsDoodads.Ui.lessMotion();
        if (reduced || typeof setInterval === 'undefined') return;
        this._lpcPreviewTimer = setInterval(() => {
            if (!this._lpcPreview || typeof document === 'undefined' || !document.getElementById('dd-lpc-preview')) { this.stopLpcPreviewTimer(); return; }
            this._lpcPreview.frame++;
            this.drawLpcPreview();
        }, 110);
    },

    stopLpcPreviewTimer() {
        if (this._lpcPreviewTimer) clearInterval(this._lpcPreviewTimer);
        this._lpcPreviewTimer = null;
    },

    // ---- The card ----

    showLpcCard() {
        if (typeof document === 'undefined') return null;
        const D = DocsDoodads, U = D.Ui, L = D.Lpc, FS = D.FS;
        let card = document.getElementById('dd-lpc-card');
        if (!card) {
            card = document.createElement('div');
            card.id = 'dd-lpc-card';
            card.className = 'dd-glass';
            document.body.appendChild(card);
        }
        const folder = this.lpcLibraryFolder(), mine = this.lpcMineFolder();
        const index = this.lpcIndex();
        const safeOnly = this.lpcSafeOnly();
        const s = index ? L.summary(index, safeOnly) : null;
        const stale = index ? this.lpcIndexStale(index) : '';
        const inside = folder && FS.path ? L.insideProject(FS.path, folder, '.') : false;
        const mineInside = mine && FS.path ? L.insideProject(FS.path, mine, '.') : false;
        const credits = this.lpcCredits();
        const images = Object.keys(credits.images).filter(img => this.lpcImageExists(img));
        const unsafe = L.unsafeImages(credits, img => this.lpcImageExists(img)).length;
        const textState = this.lpcCreditsTextState(credits);
        const day = iso => { const d = new Date(iso); return isNaN(d) ? '' : d.toLocaleDateString(); };
        const categories = s ? Object.entries(s.categories).sort((a, b) => b[1] - a[1]).map(([k, n]) => `${escapeHtml(k)} ${n}`).join(' · ') : '';
        const skipped = index && index.skipped && index.skipped.length ? index.skipped : [];
        card.innerHTML = `
            <div class="dd-panel-head"><span class="dd-grow">${U.icon('person', 1)} Characters</span>
                <button class="dd-btn dd-fold" id="dd-lpc-close" type="button" title="Close">${U.icon('close', 1)}</button></div>
            ${this.charactersGroup('mz', "RPG Maker MZ's generator parts", this.mzgenIndex() ? `${D.MzGen.summary(this.mzgenIndex()).parts} parts` : 'not scanned', this.mzgenCardHtml())}
            ${this.charactersGroup('lpc', 'The LPC character library', s ? `${s.parts} parts` : 'not scanned', `
            <div class="dd-lpc-group">Library folder (on this computer)</div>
            <div class="dd-lpc-row">
                <input type="text" id="dd-lpc-folder" value="${escapeHtml(folder)}" placeholder="The Universal LPC Spritesheet Character Generator folder" aria-label="Library folder" />
                <button class="dd-btn" id="dd-lpc-choose" type="button" title="Pick the folder">${U.icon('folder', 1)} Choose...</button>
            </div>
            ${inside ? `<div class="dd-lpc-warn"><b>This folder is inside the project.</b> MZ's Deployment copies every file in the project folder into the game, so the whole library (over a gigabyte) would ship with it. Keep the library somewhere else.</div>` : ''}
            <div class="dd-lpc-group">My parts folder (optional)</div>
            <div class="dd-lpc-row">
                <input type="text" id="dd-lpc-mine-folder" value="${escapeHtml(mine)}" placeholder="My LPC parts" aria-label="My LPC parts folder" />
                <button class="dd-btn" id="dd-lpc-mine-choose" type="button" title="Pick your parts folder">${U.icon('folder', 1)} Choose...</button>
            </div>
            ${mineInside ? '<div class="dd-lpc-warn" id="dd-lpc-mine-inside"><b>My parts is inside the project.</b> Deployment would copy the source sheets. Keep this folder somewhere else.</div>' : ''}
            <div class="dd-lpc-row">
                <button class="dd-btn dd-btn-primary" id="dd-lpc-scan" type="button" title="Read the library's parts and colours">${index ? 'Scan Again' : 'Scan the Library'}</button>
                <span class="dd-lpc-note">Reads its parts, colours and credits. The library itself is never copied into the project.</span>
            </div>
            ${s ? `<div class="dd-lpc-box" id="dd-lpc-status">
                <b>${s.parts} parts</b>${s.mine ? ` · ${s.mine} from My parts` : ''}, ${s.safe} safe to encrypt · ${s.materials} colour set${s.materials === 1 ? "" : "s"}<br>
                Scanned ${escapeHtml(day(s.built))}${s.commit ? ' · version ' + escapeHtml(s.commit.slice(0, 7)) : ''}<br>
                <span style="color: var(--dd-muted);">${categories}</span>
                ${s.skipped ? `<br><span style="color: var(--dd-warn);">${s.skipped} skipped (a format this version doesn't know):</span> ${skipped.slice(0, 6).map(k => escapeHtml(k.id + ' (' + k.why + ')')).join(', ')}${skipped.length > 6 ? ', ...' : ''}` : ''}
                ${s.newFields.length ? `<br><span style="color: var(--dd-muted);">New fields in the library, not used yet: ${escapeHtml(s.newFields.join(', '))}</span>` : ''}
            </div>` : '<div class="dd-lpc-box" id="dd-lpc-status">Not scanned yet.</div>'}
            ${stale === 'changed' ? '<div class="dd-lpc-warn" id="dd-lpc-stale">The library has changed since it was scanned. Scan again to see what is new.</div>' : ''}
            ${stale === 'missing' ? `<div class="dd-lpc-warn" id="dd-lpc-stale">The library isn't at ${escapeHtml(index.library)} any more. Choose where it is now.</div>` : ''}
            ${index && stale !== 'missing' ? `<div class="dd-lpc-group">Try it</div>
            <div class="dd-lpc-try">
                <button class="dd-btn" id="dd-lpc-turn-left" type="button" aria-label="Turn left" title="Turn left">${U.icon('left', 1)}</button>
                <canvas id="dd-lpc-preview" width="128" height="128" role="img" aria-label="A random character from the library, walking"></canvas>
                <button class="dd-btn" id="dd-lpc-turn-right" type="button" aria-label="Turn right" title="Turn right">${U.icon('right', 1)}</button>
                <div class="dd-lpc-try-side">
                    <button class="dd-btn dd-btn-primary" id="dd-lpc-shuffle" type="button" title="Another random character from the library">${U.icon('sparkle', 1)} Shuffle</button>
                    <button class="dd-btn dd-btn-good" id="dd-lpc-creator" type="button" title="Make a character from the library">${U.icon('person', 1)} Open the Creator</button>
                    <span class="dd-lpc-note" id="dd-lpc-try-note">${this._lpcPreview && this._lpcPreview.recipe ? escapeHtml(this.lpcRecipeText(this._lpcPreview.recipe)) : ''}</span>
                </div>
            </div>` : ''}
            <label title="On: the creator only offers parts whose art is offered under CC0 or OGA-BY, which allow encrypted games"><input type="checkbox" id="dd-lpc-safe" ${safeOnly ? 'checked' : ''} /> Only art that is safe to encrypt (CC0, OGA-BY)</label>
            <div class="dd-lpc-note">CC-BY and CC-BY-SA art may not be locked away, which MZ's "Encrypt image files" does. With this off you get every part${s ? ` (${s.parts} instead of ${s.safe})` : ''}, and must deploy without encrypting images that use them. This is a setting of the project.</div>
            <div class="dd-lpc-group">Credits</div>
            <div class="dd-lpc-box" id="dd-lpc-credits">
                ${images.length ? `${images.length} picture${images.length === 1 ? '' : 's'} made from the library${unsafe ? `, <b>${unsafe} can't be encrypted</b>` : ''}.<br>` : 'No pictures made from the library yet.<br>'}
                ${escapeHtml(L.creditsText)}: ${{ none: 'nothing to credit yet', missing: '<b>not written yet</b>', old: '<b>out of date</b>', ok: 'up to date' }[textState]}
            </div>
            <div class="dd-lpc-row">
                <button class="dd-btn" id="dd-lpc-credits-write" type="button" title="Write the artists, licences and links of every LPC picture into ${escapeHtml(L.creditsText)}, beside the game"${textState === 'none' ? ' disabled' : ''}>Write ${escapeHtml(L.creditsText)}</button>
            </div>
            <div class="dd-lpc-note">Every LPC artwork needs its artists credited in the game. Credits are kept per picture in ${escapeHtml(L.creditsFile)}; Problems says when ${escapeHtml(L.creditsText)} needs writing again.</div>`)}
            ${this.charactersGroup('memao', 'Memao Sprite Sheet Creator assets', this.memaoIndex() ? `${(D.Memao.summary(this.memaoIndex()) || { parts: 0 }).parts} parts` : 'not scanned', this.memaoCardHtml())}`;
        const on = (id, fn) => { const el = document.getElementById(id); if (el) el.onclick = fn; };
        const field = document.getElementById('dd-lpc-folder');
        const mineField = document.getElementById('dd-lpc-mine-folder');
        if (field) field.onchange = e => { this.setLpcLibraryFolder(e.target.value); this.refreshLpcCard(); };
        if (mineField) mineField.onchange = e => { this.setLpcMineFolder(e.target.value); this.refreshLpcCard(); };
        on('dd-lpc-close', () => this.closeLpcCard());
        on('dd-lpc-choose', () => this.pickLpcLibraryFolder());
        on('dd-lpc-mine-choose', () => this.pickLpcLibraryFolder(true));
        // A big library takes a second or so: say so first, then scan once the page has drawn it.
        on('dd-lpc-scan', () => {
            const typed = field ? field.value : folder;
            if (typed !== folder) this.setLpcLibraryFolder(typed);
            if (mineField && mineField.value !== this.lpcMineFolder()) this.setLpcMineFolder(mineField.value);
            const button = document.getElementById('dd-lpc-scan');
            if (button) { button.disabled = true; button.textContent = 'Scanning...'; }
            return new Promise(resolve => setTimeout(() => {
                this.scanLpcLibrary(this.lpcLibraryFolder());
                this.refreshLpcCard();
                resolve();
            }, 30));
        });
        const safe = document.getElementById('dd-lpc-safe');
        if (safe) safe.onchange = e => { this.setLpcSafeOnly(Boolean(e.target.checked)); this.refreshLpcCard(); };
        on('dd-lpc-credits-write', () => { this.writeLpcCreditsText(); this.refreshLpcCard(); });
        on('dd-lpc-shuffle', () => { this.shuffleLpcPreview(); this.refreshLpcCard(); });
        on('dd-lpc-creator', () => this.openCreator());
        on('dd-lpc-turn-left', () => this.turnLpcPreview(-1));
        on('dd-lpc-turn-right', () => this.turnLpcPreview(1));
        this.bindMemaoCard();
        this.bindMzGenCard();
        this.bindCharactersGroups();
        if (document.getElementById('dd-lpc-preview') && this.charactersGroupOpen('lpc')) {
            if (!this._lpcPreview || !this._lpcPreview.recipe) { this.shuffleLpcPreview(); const note = document.getElementById('dd-lpc-try-note'); if (note && this._lpcPreview) note.textContent = this.lpcRecipeText(this._lpcPreview.recipe); }
            else this.drawLpcPreview();
            this.startLpcPreviewTimer();
        }
        return card;
    },

    // ---- The card's groups: one per library, each folded or open as last left on this computer ----

    charactersGroupOpen(key) {
        const open = DocsDoodads.Ui.prefs().charGroups;
        return !(open && typeof open === 'object' && open[key] === false);
    },

    charactersGroup(key, title, status, body) {
        return `<details class="dd-chars-group" id="dd-chars-${key}"${this.charactersGroupOpen(key) ? ' open' : ''}>
            <summary><span class="dd-grow">${escapeHtml(title)}</span><span class="dd-chars-status">${escapeHtml(status)}</span></summary>
            <div class="dd-chars-body">${body}</div></details>`;
    },

    bindCharactersGroups() {
        for (const key of ['mz', 'lpc', 'memao']) {
            const el = document.getElementById('dd-chars-' + key);
            if (!el) continue;
            // A group drawn open fires a toggle as the page draws it: only a change counts.
            el.ontoggle = () => {
                if (Boolean(el.open) === this.charactersGroupOpen(key)) return;
                const U = DocsDoodads.Ui;
                const was = U.prefs().charGroups;
                U.setPref('charGroups', Object.assign({}, was && typeof was === 'object' ? was : {}, { [key]: Boolean(el.open) }));
                if (key !== 'lpc') return;
                if (!el.open) { this.stopLpcPreviewTimer(); return; }
                if (document.getElementById('dd-lpc-preview')) {
                    if (!this._lpcPreview || !this._lpcPreview.recipe) this.shuffleLpcPreview(); else this.drawLpcPreview();
                    this.startLpcPreviewTimer();
                }
            };
        }
    },

    // NW.js picks a folder with an <input type="file" nwdirectory>.
    pickLpcLibraryFolder(mine = false) {
        if (typeof document === 'undefined') return false;
        const input = document.createElement('input');
        input.type = 'file';
        if (typeof input.setAttribute === 'function') input.setAttribute('nwdirectory', '');
        input.onchange = () => {
            const chosen = input.value || (input.files && input.files[0] && input.files[0].path) || '';
            if (!chosen) return;
            if (mine) this.setLpcMineFolder(chosen); else this.setLpcLibraryFolder(chosen);
            this.refreshLpcCard();
        };
        if (typeof input.click === 'function') input.click();
        return true;
    },

    refreshLpcCard() {
        if (typeof document !== 'undefined' && document.getElementById('dd-lpc-card')) this.showLpcCard();
    },

    closeLpcCard() {
        const card = typeof document !== 'undefined' ? document.getElementById('dd-lpc-card') : null;
        if (card && card.parentNode) card.parentNode.removeChild(card);
        this.stopLpcPreviewTimer();
    }
});
// @editor-only
//==========================================================
// SECTION 25j: WORKSPACE MAP CHECK (PROBLEMS PANEL, REACHABILITY)
//==========================================================
// Problems (More): things that are probably mistakes, on this map or every map, each with Go To and,
// where it is safe, Fix. Check Reach floods the walkable tiles from the player (or a clicked tile) and
// lists the doors, chests and transfers the player can't get to.
DocsDoodads.Ui.css += `
#dd-problems { position: fixed; z-index: 10033; width: 360px; max-width: calc(100vw - 32px); max-height: 70vh; padding: 12px 14px; display: flex; flex-direction: column; gap: 8px; font-size: 11px; }
#dd-problems .dd-pr-list { overflow-y: auto; display: flex; flex-direction: column; gap: 6px; }
#dd-problems .dd-pr-group { font-weight: 900; color: var(--dd-text); font-size: 12px; margin-top: 4px; }
#dd-problems .dd-pr-row { display: flex; align-items: center; gap: 6px; padding: 5px 8px; border-radius: 10px; background: var(--dd-panel-2); }
#dd-problems .dd-pr-text { flex: 1; min-width: 0; color: var(--dd-text); font-weight: 700; overflow-wrap: anywhere; }
#dd-problems .dd-btn { padding: 3px 8px; font-size: 11px; }
#dd-problems .dd-pr-tools { display: flex; flex-wrap: wrap; gap: 6px; align-items: center; }
`;
DocsDoodads.Ui.hints.reach = 'Check Reach: click a tile to see where a player starting there can walk. Esc to stop.';
Object.assign(DocsDoodads.Ui.mapPalettes.standard, { reach: 0x22c55e });
Object.assign(DocsDoodads.Ui.mapPalettes.safe, { reach: 0x009e73 });
DocsDoodads.Ui.mapColorMeanings.push(['reach', 'Check Reach: can walk here']);

Object.assign(DocsDoodads.Workspace, {
    problemGroups: [
        ['missingArt', 'Missing pictures'], ['missingEvent', 'Missing common events'], ['missingSound', 'Missing sounds'], ['badCondition', 'Conditions that don\'t run'], ['offMap', 'Off the map'],
        ['darkLamp', 'Lamps that never show'], ['blockedEvent', 'Events that can\'t be reached or touched'], ['unreachable', 'Out of reach'],
        // Project-wide, from the LPC character library (44_workspace_lpc_library.js).
        ['lpcEncrypt', 'Pictures that can\'t be encrypted'], ['lpcCredits', 'Credits to write out'], ['artCredits', 'Art without credits']
    ],

    // ---- Collecting problems ----
    fileExists(path, cache) {
        if (cache && cache.has(path)) return cache.get(path);
        const found = Boolean(DocsDoodads.FS.existsSync && DocsDoodads.FS.existsSync(path));
        if (cache) cache.set(path, found);
        return found;
    },

    soundExists(file, cache) {
        const SS = DocsDoodads.SpatialSound;
        const f = SS.splitFile(file);
        if (!f) return true;
        return ['.ogg', '.m4a'].some(ext => this.fileExists(`audio/${f.folder}/${f.name}${ext}`, cache));
    },

    // Map sizes in tiles: this map from the game, others from their files.
    mapSize(mapId, mapData) {
        if (Number(mapId) === this.currentMapId() && window.$gameMap && $gameMap.width) return { w: $gameMap.width(), h: $gameMap.height() };
        return mapData && mapData.width ? { w: mapData.width, h: mapData.height } : null;
    },

    // The problems with the doodads of one map. mapData: the map's file (for its size), when not this map.
    conditionCompiles(source) {
        try { new Function(`return (${source});`); return true; } catch (error) { return false; }
    },

    doodadProblems(mapId, list, mapData, cache) {
        const out = [];
        const tw = window.$gameMap && $gameMap.tileWidth ? $gameMap.tileWidth() : 48;
        const th = window.$gameMap && $gameMap.tileHeight ? $gameMap.tileHeight() : 48;
        const size = this.mapSize(mapId, mapData);
        const settings = DocsDoodads.Lighting.mapSettings(mapId) || {};
        const dark = DocsDoodads.MapCheck.canBeDark(settings, DocsDoodads.World.settings());
        const here = Number(mapId) === this.currentMapId();
        (list || []).forEach((d, i) => {
            if (!d) return;
            const name = d.bit && d.bit[0] === 3 ? String(d.bit[1]).split('/').pop() : `doodad #${i + 1}`;
            const where = { mapId: Number(mapId), doodad: d, x: Math.floor(d.x / tw), y: Math.floor((d.y - 1) / th) };
            if (d.bit && d.bit[0] === 3 && !this.fileExists(d.bit[1], cache)) {
                out.push(Object.assign({ kind: 'missingArt', text: `${name} (map ${mapId}): ${d.bit[1]} is not in the project.` }, where,
                    here ? { fix: { label: 'Replace Art...', run: () => { this.selectDoodads([d]); return this.showReplaceArt(); } } } : {}));
            }
            // A state's own art, which can go missing on its own.
            DocsDoodads.States.list(d).forEach((st, si) => {
                if (si === 0 || !st || !st.path || this.fileExists(st.path, cache)) return;
                out.push(Object.assign({ kind: 'missingArt', text: `${name} (map ${mapId}), state "${st.name || si}": ${st.path} is not in the project.` }, where,
                    { fix: { label: 'Use Own Art', run: () => this.editDoodads([d], x => {
                        const s2 = x.states && x.states.list && x.states.list[si];
                        if (s2) { delete s2.path; delete s2.w; delete s2.h; }
                    }, 'edit_states') } }));
            });
            const touchId = d.touch ? Number(d.touch.commonEventId) || 0 : 0;
            if (touchId > 0 && typeof $dataCommonEvents !== 'undefined' && Array.isArray($dataCommonEvents) && !$dataCommonEvents[touchId]) {
                out.push(Object.assign({ kind: 'missingEvent', text: `${name} (map ${mapId}) runs common event ${touchId} when touched, which doesn't exist.` }, where,
                    { fix: { label: 'Stop Running It', run: () => this.editDoodads([d], x => this.applyDoodadProperty(x, 'touch.commonEventId', 0), 'edit_doodads') } }));
            }
            if (d.sound && d.sound.file && !this.soundExists(d.sound.file, cache)) {
                out.push(Object.assign({ kind: 'missingSound', text: `${name} (map ${mapId}) plays ${d.sound.file}, which is not in audio/.` }, where,
                    { fix: { label: 'Remove Sound', run: () => this.editDoodads([d], x => { delete x.sound; }, 'edit_doodads') } }));
            }
            // A condition is JavaScript (SECURITY.md); one that doesn't compile is taken as true, so it always shows.
            const condition = String(d.condition || '').trim();
            if (condition && !this.conditionCompiles(condition)) {
                out.push(Object.assign({ kind: 'badCondition', text: `${name} (map ${mapId}): its condition "${condition.slice(0, 60)}" isn't JavaScript that runs, so it always shows.` }, where,
                    { fix: { label: 'Remove Condition', run: () => this.editDoodads([d], x => { x.condition = ''; }, 'edit_doodads') } }));
            }
            if (size && d.posMode !== 0) {
                const maxX = size.w * tw, maxY = size.h * th;
                if (d.x < 0 || d.y < 0 || d.x > maxX || d.y > maxY) {
                    out.push(Object.assign({ kind: 'offMap', text: `${name} (map ${mapId}) stands outside the ${size.w}×${size.h} map, at ${Math.round(d.x)}, ${Math.round(d.y)}.` }, where, {
                        fix: { label: 'Move Inside', run: () => this.editDoodads([d], x => {
                            x.x = Math.max(tw / 2, Math.min(maxX - tw / 2, x.x));
                            x.y = Math.max(th, Math.min(maxY, x.y));
                        }, 'move_doodads') }
                    }));
                }
            }
            if (d.light && d.light.enabled && !dark) {
                out.push(Object.assign({ kind: 'darkLamp', text: `${name} (map ${mapId}) has a light, but the map never gets dark (no darkness, no day and night), so it won't show unless Set Ambient Light is used.` }, where));
            }
        });
        return out;
    },

    // This map's events: below the player and touched to start, but on a tile nobody can step on; or on
    // a tile a doodad's collision covers.
    eventProblems() {
        const out = [];
        if (!window.$gameMap || typeof $gameMap.events !== 'function') return out;
        const blocked = this.doodadBlockedTiles();
        for (const ge of $gameMap.events()) {
            if (!ge || typeof ge.event !== 'function') continue;
            const data = ge.event() || {};
            const label = `EV${String(ge.eventId()).padStart(3, '0')}${data.name ? ' ' + data.name : ''}`;
            const where = { mapId: this.currentMapId(), event: ge, x: ge.x, y: ge.y };
            const page = typeof ge.page === 'function' ? ge.page() : null;
            const touch = page && (page.trigger === 1 || page.trigger === 2) && page.priorityType === 0;
            const walkable = [2, 4, 6, 8].some(dir => $gameMap.isPassable(ge.x, ge.y, dir));
            if (touch && !walkable) out.push(Object.assign({ kind: 'blockedEvent', text: `${label} starts when stepped on, but nobody can walk onto its tile.` }, where));
            else if (blocked.has(ge.x + ',' + ge.y) && page && page.list && page.list.length > 1) {
                out.push(Object.assign({ kind: 'blockedEvent', text: `${label} is under a doodad's collision: the player can't stand there.` }, where));
            }
        }
        return out;
    },

    // Tiles blocked by the collision of doodads that show in the game.
    doodadBlockedTiles() {
        const C = DocsDoodads.Collision;
        const tw = $gameMap.tileWidth(), th = $gameMap.tileHeight();
        const settings = DocsDoodads.Lighting.mapSettings($gameMap.mapId());
        const out = new Set();
        for (const d of DocsDoodads.doodads() || []) {
            const body = C.bodyOf(d);
            if (!body || !DocsDoodads.Layers.visibleInGame(d, settings) || !DocsDoodads.Appearance.isVisible(d, {})) continue;
            for (const t of C.tilesUnder(body, tw, th)) out.add(t.x + ',' + t.y);
        }
        return out;
    },

    // scope: 'map' (this map, with its events) or 'all' (every map's doodads, read from their files).
    collectProblems(scope = 'map') {
        const cache = new Map();
        const data = window.$dataDocsDoodads || {};
        const here = this.currentMapId();
        let out = this.doodadProblems(here, DocsDoodads.doodads(here), null, cache).concat(this.eventProblems());
        if (scope === 'all') {
            for (const id of Object.keys(data).filter(k => /^\d+$/.test(k) && Number(k) !== here && Array.isArray(data[k]) && data[k].length)) {
                const mapData = DocsDoodads.FS.readJson(DocsDoodads.Persistence.mapFilePath(id));
                out = out.concat(this.doodadProblems(Number(id), data[id], mapData, cache));
            }
        }
        if (this._reach && this._reach.mapId === here) out = out.concat(this._reach.flagged);
        // Project-wide: LPC pictures and their credits (no map to go to).
        if (typeof this.lpcProblems === 'function') out = out.concat(this.lpcProblems());
        const clash = DocsDoodads.Clash, plugins = window.$plugins || [];
        if (clash) out = out.concat(clash.check(plugins), clash.hookFindings(plugins));
        if (this.shippedProblems && this.shippedRelease()) out = out.concat(this.shippedProblems());
        if (this.creditProblems) out = out.concat(this.creditProblems());
        if (this.pinProblems) out = out.concat(this.pinProblems());
        return out;
    },

    // ---- Reachability ----
    // ignoreCharacters: let the player through events that stand in the way (they may move).
    reachMap(ignoreCharacters) {
        const gameMap = window.$gameMap;
        const blocked = this.doodadBlockedTiles();
        const blockers = new Set();
        for (const ge of ignoreCharacters ? [] : gameMap.events()) {
            if (ge && ge.isNormalPriority && ge.isNormalPriority() && !(ge.isThrough && ge.isThrough())) blockers.add(ge.x + ',' + ge.y);
        }
        const reverse = { 2: 8, 4: 6, 6: 4, 8: 2 };
        return {
            width: gameMap.width(), height: gameMap.height(),
            loopX: Boolean(gameMap.isLoopHorizontal && gameMap.isLoopHorizontal()), loopY: Boolean(gameMap.isLoopVertical && gameMap.isLoopVertical()),
            canStep: (x, y, dir) => {
                const nx = gameMap.roundXWithDirection(x, dir), ny = gameMap.roundYWithDirection(y, dir);
                if (!gameMap.isValid(nx, ny)) return false;
                if (!gameMap.isPassable(x, y, dir) || !gameMap.isPassable(nx, ny, reverse[dir])) return false;
                const key = nx + ',' + ny;
                return !blocked.has(key) && !blockers.has(key);
            }
        };
    },

    // What kind of place an event is, for the reach check: a transfer, a door, a chest, or null.
    eventPlaceKind(ge) {
        const data = ge && typeof ge.event === 'function' ? ge.event() || {} : {};
        const pages = data.pages || [];
        if (pages.some(p => (p.list || []).some(c => c && c.code === 201))) return 'transfer';
        const names = [data.name || ''].concat(pages.map(p => (p.image && p.image.characterName) || '')).join(' ');
        if (/chest|treasure/i.test(names)) return 'chest';
        if (/door|gate/i.test(names)) return 'door';
        return null;
    },

    // From the player (or a tile): reachable tiles, and the places out of reach.
    checkReach(start) {
        if (!window.$gameMap || typeof $gameMap.events !== 'function') return null;
        start = start || (window.$gamePlayer ? { x: $gamePlayer.x, y: $gamePlayer.y } : { x: 0, y: 0 });
        const map = this.reachMap();
        const result = DocsDoodads.MapCheck.reach(start, map);
        const loop = { x: map.loopX, y: map.loopY };
        const flagged = [];
        let open = null;
        for (const ge of $gameMap.events()) {
            const kind = this.eventPlaceKind(ge);
            if (!kind || DocsDoodads.MapCheck.nearReached(result.seen, map.width, map.height, ge.x, ge.y, loop)) continue;
            const data = ge.event() || {};
            // Only characters in the way? Say so: they may walk off or step aside during play.
            if (!open) open = DocsDoodads.MapCheck.reach(start, this.reachMap(true));
            const byCharacters = DocsDoodads.MapCheck.nearReached(open.seen, map.width, map.height, ge.x, ge.y, loop);
            flagged.push({ kind: 'unreachable', mapId: this.currentMapId(), event: ge, x: ge.x, y: ge.y, byCharacters,
                text: `The ${kind} EV${String(ge.eventId()).padStart(3, '0')}${data.name ? ' ' + data.name : ''} at ${ge.x}, ${ge.y} can't be reached from ${start.x}, ${start.y}.` +
                    (byCharacters ? ' Only a character stands in the way (it may move or step aside).' : '') });
        }
        this._reach = { mapId: this.currentMapId(), start, seen: result.seen, count: result.count, width: map.width, height: map.height, flagged };
        this.showToast(flagged.length ? `${result.count} tiles reachable; ${flagged.length} place(s) out of reach.` : `${result.count} tiles reachable; every door, chest and transfer can be reached.`, flagged.length ? 'info' : 'success');
        if (this._problemsOpen) this.renderProblems();
        return this._reach;
    },

    clearReach() {
        this._reach = null;
        if (this.placementTool === 'reach') this.setPlacementTool(null);
        if (this._problemsOpen) this.renderProblems();
    },

    drawReachOverlay(g) {
        const r = this._reach;
        if (!r || !window.$gameMap || r.mapId !== this.currentMapId()) return;
        if (DocsDoodads.Perspective.liveCamera && DocsDoodads.Perspective.liveCamera()) return;
        const tw = $gameMap.tileWidth(), th = $gameMap.tileHeight();
        const width = typeof Graphics !== 'undefined' ? Graphics.width : 816, height = typeof Graphics !== 'undefined' ? Graphics.height : 624;
        const x0 = Math.floor($gameMap.displayX()), y0 = Math.floor($gameMap.displayY());
        g.lineStyle(0);
        g.beginFill(DocsDoodads.Ui.mapColor('reach'), 0.3);
        for (let y = y0; y <= y0 + Math.ceil(height / th); y++) {
            for (let x = x0; x <= x0 + Math.ceil(width / tw); x++) {
                const mx = $gameMap.roundX ? $gameMap.roundX(x) : x, my = $gameMap.roundY ? $gameMap.roundY(y) : y;
                if (mx < 0 || my < 0 || mx >= r.width || my >= r.height || !r.seen[mx + my * r.width]) continue;
                g.drawRect($gameMap.adjustX(mx) * tw, $gameMap.adjustY(my) * th, tw, th);
            }
        }
        g.endFill();
        g.lineStyle(3, DocsDoodads.Ui.mapColor('warning'), 1);
        for (const f of r.flagged) g.drawRect($gameMap.adjustX(f.x) * tw + 2, $gameMap.adjustY(f.y) * th + 2, tw - 4, th - 4);
        g.lineStyle(3, DocsDoodads.Ui.mapColor('probe'), 1);
        g.drawCircle(($gameMap.adjustX(r.start.x) + 0.5) * tw, ($gameMap.adjustY(r.start.y) + 0.5) * th, 8);
        g.lineStyle(0);
    },

    // ---- Go To ----
    goToProblem(p) {
        if (!p) return;
        if (p.mapId !== this.currentMapId()) {
            this._pendingGoTo = p;
            this.goToMap(p.mapId);
            return;
        }
        this.centerOnTile(p.x, p.y);
        if (p.doodad) this.selectDoodads([p.doodad]);
        else if (p.event) this.selectEvent({ gameEvent: p.event, stagedEvent: ($gameMap._stagedMapData && $gameMap._stagedMapData.events && $gameMap._stagedMapData.events[p.event.eventId()]) || p.event.event() });
    },

    centerOnTile(x, y) {
        if (!window.$gameMap || typeof $gameMap.setDisplayPos !== 'function') return;
        const sw = typeof Graphics !== 'undefined' ? Graphics.width / $gameMap.tileWidth() : 17;
        const sh = typeof Graphics !== 'undefined' ? Graphics.height / $gameMap.tileHeight() : 13;
        $gameMap.setDisplayPos(x - sw / 2 + 0.5, y - sh / 2 + 0.5);
    },

    // After Go To on another map: once it loads, the problem is shown there.
    finishPendingGoTo() {
        const p = this._pendingGoTo;
        if (!p || p.mapId !== this.currentMapId()) return false;
        this._pendingGoTo = null;
        this.goToProblem(p);
        return true;
    },

    // ---- The panel ----
    showProblems() {
        if (typeof document === 'undefined') return null;
        this._problemsOpen = true;
        this._problemScope = this._problemScope || 'map';
        return this.renderProblems();
    },

    closeProblems() {
        this._problemsOpen = false;
        const el = typeof document !== 'undefined' ? document.getElementById('dd-problems') : null;
        if (el && el.parentNode) el.parentNode.removeChild(el);
    },

    renderProblems() {
        if (typeof document === 'undefined' || !this._problemsOpen) return null;
        const U = DocsDoodads.Ui;
        let panel = document.getElementById('dd-problems');
        if (!panel) {
            panel = document.createElement('div');
            panel.id = 'dd-problems';
            panel.className = 'dd-glass';
            document.body.appendChild(panel);
        }
        const problems = this.collectProblems(this._problemScope);
        this._problems = problems;
        panel.innerHTML = `
            <div class="dd-panel-head"><span class="dd-grow">${U.icon('help', 1)} Problems (${problems.length})</span>
                <button class="dd-btn dd-fold" id="dd-pr-close" type="button" title="Close">${U.icon('close', 1)}</button></div>
            <div class="dd-pr-tools">
                <label><input type="checkbox" id="dd-pr-credits" ${U.prefs().checkArtCredits ? 'checked' : ''} /> Check art credits</label>
                <select id="dd-pr-scope"><option value="map"${this._problemScope === 'map' ? ' selected' : ''}>This map</option><option value="all"${this._problemScope === 'all' ? ' selected' : ''}>Every map</option></select>
                <button class="dd-btn" id="dd-pr-refresh" type="button">Check Again</button>
                <button class="dd-btn" id="dd-pr-reach" type="button" title="Where the player can walk from where they stand">Check Reach</button>
                <button class="dd-btn" id="dd-pr-reach-tile" type="button" title="Pick the start tile on the map">From a Tile...</button>
                ${this._reach ? '<button class="dd-btn" id="dd-pr-reach-clear" type="button">Hide Reach</button>' : ''}
            </div>
            <div class="dd-pr-list" id="dd-pr-list"></div>`;
        const list = document.getElementById('dd-pr-list');
        if (list) {
            if (!problems.length) {
                const empty = document.createElement('div');
                empty.className = 'dd-empty';
                empty.textContent = this._problemScope === 'all' ? 'No problems found on any map.' : 'No problems found on this map.';
                list.appendChild(empty);
            }
            for (const [kind, title] of this.problemGroups) {
                const rows = problems.filter(p => p.kind === kind);
                if (!rows.length) continue;
                const head = document.createElement('div');
                head.className = 'dd-pr-group';
                head.textContent = `${title} (${rows.length})`;
                list.appendChild(head);
                for (const p of rows) {
                    const row = document.createElement('div');
                    row.className = 'dd-pr-row';
                    const text = document.createElement('span');
                    text.className = 'dd-pr-text';
                    text.textContent = p.text;
                    row.appendChild(text);
                    if (!p.global) {
                        const go = document.createElement('button');
                        go.className = 'dd-btn';
                        go.type = 'button';
                        go.textContent = 'Go To';
                        go.onclick = () => this.goToProblem(p);
                        row.appendChild(go);
                    }
                    if (p.fix) {
                        const fix = document.createElement('button');
                        fix.className = 'dd-btn dd-btn-primary';
                        fix.type = 'button';
                        fix.textContent = p.fix.label;
                        fix.onclick = async () => { await p.fix.run(); this.renderProblems(); };
                        row.appendChild(fix);
                    }
                    list.appendChild(row);
                }
            }
        }
        const on = (id, run) => { const el = document.getElementById(id); if (el) el.onclick = run; };
        on('dd-pr-close', () => this.closeProblems());
        on('dd-pr-refresh', () => this.renderProblems());
        const credits = document.getElementById('dd-pr-credits');
        if (credits) credits.onchange = () => { U.setPref('checkArtCredits', Boolean(credits.checked)); this.renderProblems(); };
        on('dd-pr-reach', () => this.checkReach());
        on('dd-pr-reach-tile', () => this.setPlacementTool('reach'));
        on('dd-pr-reach-clear', () => this.clearReach());
        const scope = document.getElementById('dd-pr-scope');
        if (scope) scope.onchange = () => { this._problemScope = scope.value === 'all' ? 'all' : 'map'; this.renderProblems(); };
        this.placeReadouts();
        return panel;
    }
});
// @editor-only
//==========================================================
// SECTION 25M: PICTURE TO MAP (8.5.2) AND KINDS OF MAP (8.5.3)
//==========================================================
// Map → Picture to Map: choose what kind of map, a picture (and a grey one for heights), how thin a line to
// ignore, then agree the key: each colour group beside a class, guessed and always changeable, and the tile each
// class uses (remembered per tileset). The plan shows on the map; Apply paints tiles (autotile edges joined),
// regions, heights and biome art as one undo step. Kinds: four built in, and copies the user changes.
(function() {
    const D = DocsDoodads, W = D.Workspace, M = D.MapFrom;
    const escapeHtml = value => D.Security.escapeHtml(String(value));
    const hex = c => '#' + c.map(v => Math.max(0, Math.min(255, v)).toString(16).padStart(2, '0')).join('');

    Object.assign(W, {
        mapKinds() { return M.kinds(window.$dataDocsDoodads && window.$dataDocsDoodads.mapKinds); },

        // The tile each class uses, per tileset and kind, kept on this computer.
        mapFromTile(kindId, classId, value) {
            const tileset = (window.$dataMap && $dataMap.tilesetId) || 0, prefs = D.Ui.prefs().mapFromTiles || {};
            const key = `${tileset}:${kindId}`;
            if (value === undefined) {
                const saved = prefs[key] && prefs[key][classId];
                if (saved) return saved;
                const cls = M.kind(kindId, window.$dataDocsDoodads && window.$dataDocsDoodads.mapKinds).classes.find(c => c.id === classId);
                return cls && cls.tile ? cls.tile : null;
            }
            const next = Object.assign({}, prefs, { [key]: Object.assign({}, prefs[key] || {}, { [classId]: Number(value) > 0 ? Math.floor(Number(value)) : null }) });
            D.Ui.setPref('mapFromTiles', next);
            return next[key][classId];
        },

        copyMapKind(kindId, name) {
            const data = window.$dataDocsDoodads = window.$dataDocsDoodads || {};
            const kinds = this.mapKinds(), from = kinds.find(k => k.id === kindId);
            if (!from) return null;
            let id = 'kind_' + String(name || from.id).toLowerCase().replace(/[^\w]+/g, '_').slice(0, 30), n = 2;
            while (kinds.some(k => k.id === id)) id = id.replace(/_\d+$/, '') + '_' + n++;
            const copy = M.copyKind(from, id, name || from.name + ' (copy)');
            data.mapKinds = (Array.isArray(data.mapKinds) ? data.mapKinds : []).concat([copy]);
            D.Persistence.dirtyDoodads = true;
            return copy;
        },

        loadMapFromPicture(file) {
            return new Promise((resolve, reject) => {
                const url = typeof URL !== 'undefined' && URL.createObjectURL && file instanceof Blob ? URL.createObjectURL(file) : String(file);
                const image = new Image();
                image.onload = () => {
                    const canvas = document.createElement('canvas');
                    canvas.width = image.naturalWidth || image.width; canvas.height = image.naturalHeight || image.height;
                    const ctx = canvas.getContext('2d');
                    ctx.drawImage(image, 0, 0);
                    resolve({ data: ctx.getImageData(0, 0, canvas.width, canvas.height).data, width: canvas.width, height: canvas.height });
                };
                image.onerror = () => reject(new Error('That picture could not be read.'));
                image.src = url;
            });
        },

        // From the state of the card: the read picture, the key and the plan.
        mapFromPlan(state) {
            if (!state.picture || !window.$gameMap) return null;
            const kind = this.mapKinds().find(k => k.id === state.kindId) || this.mapKinds()[0];
            const tilesW = $gameMap.width(), tilesH = $gameMap.height();
            const read = M.read(state.picture.data, state.picture.width, state.picture.height, { tilesW, tilesH });
            read.cells = M.ignoreThin(read.cells, read.w, read.h, state.thin);
            if (!state.key || state.key.length !== read.groups.length || state.keyKind !== kind.id) {
                state.key = read.groups.map(g => M.guess(g.colour, kind));
                state.keyKind = kind.id;
            }
            const heights = state.heights ? M.heightsFrom(state.heights.data, state.heights.width, state.heights.height, tilesW, tilesH) : null;
            const plan = M.plan(read, state.key, kind, { heights, name: state.roomName, roughen: state.roughen, seed: state.seed || 1 });
            return { kind, read, plan, ppt: M.pixelsPerTile(state.picture.width, state.picture.height, tilesW, tilesH) };
        },

        // Apply: tiles through Tiles.paint (autotile edges join up), regions, heights and biome art, one undo step.
        applyMapFrom(plan, kind, tileFor = id => this.mapFromTile(kind.id, id)) {
            const view = this.tileMapView ? this.tileMapView() : null;
            if (!view) { this.showToast('Open a map first.', 'error'); return null; }
            const built = M.build(plan, kind, tileFor), mapId = this.currentMapId(), T = D.Tiles, tables = this.autotileTables();
            const tileChanges = new Map();
            const record = (index, after) => {
                const before = tileChanges.has(index) ? tileChanges.get(index).before : Number(view.data[index]) || 0;
                tileChanges.set(index, { before, after });
                this.setMapTile(mapId, index, after);
            };
            for (const t of built.tiles) for (const c of T.paint(view, t.x, t.y, { ids: [[t.id]], layer: 'auto' }, tables)) record(c.index, c.after);
            for (const r of built.regions) record(T.index(view.width, view.height, r.x, r.y, 5), r.id);
            const before = JSON.parse(JSON.stringify(D.Lighting.mapSettings(mapId) || {}));
            const after = JSON.parse(JSON.stringify(before));
            // The kind is kept with the map, so later tools know what it is.
            after.mapKind = kind.id;
            if (Object.keys(built.heights).length) {
                after.terrain = Object.assign({}, after.terrain || {}, { enabled: true });
                after.terrain.paint = Object.assign({}, D.Terrain.normalize(after.terrain).paint, built.heights);
            }
            // Biome art: one scatter per tile of a class with a biome, seeded so Apply twice makes the same map.
            const list = window.$dataDocsDoodads[mapId] = window.$dataDocsDoodads[mapId] || [];
            const biomes = this.biomesRaw ? this.biomesRaw() : [], placed = [], rng = D.Scatter.rng(Number(plan.options && plan.options.seed) || 1);
            const tw = $gameMap.tileWidth(), th = $gameMap.tileHeight(), missingBiomes = new Set();
            for (const spot of built.biomes) {
                const raw = biomes.find(b => b && (b.id === spot.biome || String(b.name || '').toLowerCase() === spot.biome.toLowerCase()));
                const biome = raw ? D.Biome.normalize(raw) : null;
                if (!biome || !biome.entries.length) { missingBiomes.add(spot.biome); continue; }
                const center = { x: spot.x * tw + tw / 2, y: spot.y * th + th / 2 };
                const existing = placed.filter(d => Math.abs(d.x - center.x) < tw * 2 && Math.abs(d.y - center.y) < th * 2).map(d => ({ x: d.x, y: d.y }));
                for (const p of D.Biome.paint(biome, center, tw / 2, existing, rng)) {
                    const asset = this.assetByPath ? this.assetByPath(p.path) : null;
                    const d = asset ? this.newDoodadFromAsset(asset, p.x, p.y, false) : Object.assign(D.standardStruct(), { bit: [3, p.path], x: p.x, y: p.y });
                    d.scaleX = p.scale * (p.flipX ? -1 : 1); d.scaleY = p.scale;
                    placed.push(d);
                }
            }
            const changes = Array.from(tileChanges.entries()).filter(([, c]) => c.before !== c.after);
            const setTiles = which => { for (const [index, c] of changes) this.setMapTile(mapId, index, c[which]); if (this.afterTileEdit) this.afterTileEdit(); };
            const setSettings = value => { if (this.writeMapSettings) this.writeMapSettings(mapId, JSON.parse(JSON.stringify(value))); else D.Lighting.setMapSettings(mapId, value); };
            const setDoodads = add => {
                for (const d of placed) { const at = list.indexOf(d); if (add && at < 0) list.push(d); if (!add && at >= 0) list.splice(at, 1); }
                D.Persistence.dirtyDoodads = true;
                if (this.refreshSpriteset) this.refreshSpriteset(true);
            };
            setTiles('before');
            D.Undo.execute({
                type: 'picture_to_map',
                apply: () => { setTiles('after'); setSettings(after); setDoodads(true); },
                revert: () => { setTiles('before'); setSettings(before); setDoodads(false); }
            });
            const notes = [];
            if (built.unmapped.length) notes.push(`No tile chosen for ${built.unmapped.map(id => (kind.classes.find(c => c.id === id) || { name: id }).name).join(', ')}: left alone.`);
            if (missingBiomes.size) notes.push(`No biome with art called ${Array.from(missingBiomes).join(', ')}.`);
            this.showToast(`Picture to Map: ${changes.length} tile change(s), ${placed.length} doodad(s). ${notes.join(' ')}`.trim(), notes.length ? 'info' : 'success');
            return { changes: changes.length, doodads: placed.length, unmapped: built.unmapped, missingBiomes: Array.from(missingBiomes) };
        },

        // The plan on the map while the card is open: a colour per class.
        drawMapFromPlan(g) {
            const preview = this._mapFrom && this._mapFrom.preview;
            if (!preview || typeof $gameMap === 'undefined' || !$gameMap || (D.Perspective.liveCamera && D.Perspective.liveCamera())) return;
            const { plan, kind } = preview, tw = $gameMap.tileWidth(), th = $gameMap.tileHeight();
            const colour = id => { let h = 0; for (const ch of id) h = (h * 31 + ch.charCodeAt(0)) >>> 0; return ((h & 0x7f) + 96) << 16 | (((h >> 7) & 0x7f) + 96) << 8 | (((h >> 14) & 0x7f) + 96); };
            plan.cells.forEach((id, i) => {
                if (!id || !kind.classes.some(c => c.id === id)) return;
                const x = $gameMap.adjustX(i % plan.w) * tw, y = $gameMap.adjustY(Math.floor(i / plan.w)) * th;
                g.beginFill(colour(id), 0.35); g.drawRect(x, y, tw, th); g.endFill();
            });
            for (const f of plan.features) {
                const x = $gameMap.adjustX(f.x) * tw, y = $gameMap.adjustY(f.y) * th;
                g.lineStyle(2, 0xffffff, 0.9); g.drawRect(x + 2, y + 2, f.w * tw - 4, f.h * th - 4); g.lineStyle(0);
            }
        },

        closeMapFrom() {
            const card = typeof document !== 'undefined' && document.getElementById ? document.getElementById('dd-map-from') : null;
            if (card && card.parentNode) card.parentNode.removeChild(card);
            this._mapFrom = null;
        },

        openMapFrom() {
            if (typeof document === 'undefined') return null;
            this.closeMapFrom();
            const state = this._mapFrom = { kindId: 'overworld', thin: 0, roughen: 0, roomName: '', picture: null, heights: null, key: null, preview: null, error: '' };
            const card = document.createElement('div');
            card.id = 'dd-map-from'; card.className = 'dd-glass';
            card.style.cssText = 'position:fixed;top:80px;right:20px;width:380px;max-height:78vh;overflow:auto;padding:12px;z-index:10040;font-size:11px;display:flex;flex-direction:column;gap:6px;';
            const render = () => {
                let made = null;
                try { made = this.mapFromPlan(state); state.error = ''; } catch (error) { state.error = error.message || String(error); }
                state.preview = made ? { plan: made.plan, kind: made.kind } : null;
                const kinds = this.mapKinds(), kind = made ? made.kind : kinds.find(k => k.id === state.kindId) || kinds[0];
                const classOptions = selected => `<option value=""${!selected ? ' selected' : ''}>Leave alone</option>` + kind.classes.map(c => `<option value="${escapeHtml(c.id)}"${c.id === selected ? ' selected' : ''}>${escapeHtml(c.name)}</option>`).join('');
                const used = made ? Array.from(new Set(made.plan.cells.filter(Boolean))) : [];
                card.innerHTML = `<div class="dd-panel-head">Picture to Map <button class="dd-btn" id="dd-mf-close" type="button">Close</button></div>
                    <label>Kind of map <select id="dd-mf-kind">${kinds.map(k => `<option value="${escapeHtml(k.id)}"${k.id === kind.id ? ' selected' : ''}>${escapeHtml(k.name)}</option>`).join('')}</select>
                    <button class="dd-btn" id="dd-mf-copy" type="button">Copy Kind</button></label>
                    <div style="color:var(--dd-muted);">${escapeHtml(kind.scale)}</div>
                    ${(kind.base || kind.id) === 'room' ? `<label>Room name (for furniture) <input id="dd-mf-room" type="text" value="${escapeHtml(state.roomName)}"></label>` : ''}
                    ${(kind.base || kind.id) === 'dungeon' ? `<label>Cave walls (rough) <input id="dd-mf-rough" type="range" min="0" max="1" step="0.1" value="${state.roughen}"></label>` : ''}
                    <label>Picture <input id="dd-mf-picture" type="file" accept="image/png,image/jpeg,image/webp"></label>
                    <label>Heights (grey: dark low, light high) <input id="dd-mf-heights" type="file" accept="image/png,image/jpeg,image/webp"></label>
                    <label>Ignore lines (labels, grid lines) up to <select id="dd-mf-thin">${[0, 1, 2, 3].map(n => `<option value="${n}"${state.thin === n ? ' selected' : ''}>${n ? n + ' tile(s) thick' : 'nothing'}</option>`).join('')}</select></label>
                    ${made ? `<div>${$gameMap.width()} × ${$gameMap.height()} tiles; about ${Math.round(made.ppt * 10) / 10} picture pixels a tile.${made.ppt < 2 ? ' <b>Under two pixels a tile: draw it bigger or make the map smaller.</b>' : ''}</div>` : ''}
                    ${state.error ? `<div style="color:#f87171;">${escapeHtml(state.error)}</div>` : ''}
                    ${made ? made.read.groups.map((g, i) => `<label style="display:flex;gap:6px;align-items:center;"><span style="display:inline-block;width:18px;height:18px;border-radius:4px;background:${hex(g.colour)};"></span>${g.count} tile(s)
                        <select id="dd-mf-key-${i}">${classOptions(state.key[i])}</select></label>`).join('') : ''}
                    ${used.length ? `<div class="dd-panel-head" style="margin-top:4px;">Tiles</div>` + used.map(id => `<label>${escapeHtml((kind.classes.find(c => c.id === id) || { name: id }).name)}
                        <input id="dd-mf-tile-${escapeHtml(id)}" type="number" min="0" value="${this.mapFromTile(kind.id, id) || ''}" placeholder="tile id"></label>`).join('') +
                        `<div style="color:var(--dd-muted);">Alt+click a tile with the Tiles tool to see its id. Classes with no tile are left alone.</div>` : ''}
                    <button class="dd-btn dd-btn-primary" id="dd-mf-apply" type="button"${made ? '' : ' disabled'}>Apply</button>`;
                const node = id => document.getElementById(id);
                node('dd-mf-close').onclick = () => this.closeMapFrom();
                node('dd-mf-kind').onchange = event => { state.kindId = event.target.value; state.key = null; render(); };
                node('dd-mf-copy').onclick = async () => {
                    const name = await D.Ui.prompt('A name for the copy', kind.name + ' (mine)', { title: 'Copy Kind' });
                    const copy = name ? this.copyMapKind(kind.id, name) : null;
                    if (copy) { state.kindId = copy.id; render(); }
                };
                const room = node('dd-mf-room'); if (room) room.onchange = () => { state.roomName = room.value; render(); };
                const rough = node('dd-mf-rough'); if (rough) rough.onchange = () => { state.roughen = Number(rough.value) || 0; render(); };
                node('dd-mf-thin').onchange = event => { state.thin = Number(event.target.value) || 0; render(); };
                const pick = (id, field) => {
                    node(id).onchange = async event => {
                        const file = event.target.files && event.target.files[0];
                        if (!file) return;
                        try { state[field] = await this.loadMapFromPicture(file); if (field === 'picture') state.key = null; } catch (error) { state.error = error.message; }
                        render();
                    };
                };
                pick('dd-mf-picture', 'picture'); pick('dd-mf-heights', 'heights');
                if (made) made.read.groups.forEach((g, i) => { node(`dd-mf-key-${i}`).onchange = event => { state.key[i] = event.target.value || null; render(); }; });
                for (const id of used) { const input = node(`dd-mf-tile-${id}`); if (input) input.onchange = () => this.mapFromTile(kind.id, id, input.value); }
                node('dd-mf-apply').onclick = () => { if (made) { this.applyMapFrom(made.plan, made.kind); this.closeMapFrom(); } };
            };
            document.body.appendChild(card);
            render();
            return card;
        }
    });

    W.toolHooks.mapFrom = { overlay(g) { this.drawMapFromPlan(g); } };
    const menus = W.menus;
    W.menus = function() {
        const all = menus.call(this), map = all.find(menu => menu.id === 'map');
        if (map) map.items.push({ id: 'dd-map-from-btn', icon: 'picture', label: 'Picture to Map', title: 'Turn a drawing into tiles, hills and doodads, after agreeing a colour key' });
        return all;
    };
    const bind = W.bindEvents;
    W.bindEvents = function() {
        const result = bind.apply(this, arguments), button = typeof document !== 'undefined' ? document.getElementById('dd-map-from-btn') : null;
        if (button) button.onclick = () => { this.showMoreMenu(false); this.openMapFrom(); };
        return result;
    };
})();
// @editor-only
//==========================================================
// SECTION 25W: SAVE 3D MAP AS FILE (8.4.8)
//==========================================================
// Map → Save 3D Map as File writes the ground (the 3D view's terrain, or two triangles for a flat map) with the
// map's tiles as its picture, and the standing doodads as upright pictures, into one .glb in screenshots/, for
// Blender, a trailer or a 3D print. It asks first and says that the file carries the project's art.
(function() {
    const D = DocsDoodads, W = D.Workspace, GW = D.GltfWrite;

    Object.assign(W, {
        mapGlbName(mapId, date = new Date()) {
            const p = n => String(n).padStart(2, '0');
            return `Map${String(mapId).padStart(3, '0')}_3d_${date.getFullYear()}${p(date.getMonth() + 1)}${p(date.getDate())}-${p(date.getHours())}${p(date.getMinutes())}${p(date.getSeconds())}.glb`;
        },

        standingDoodads() {
            const settings = D.Lighting.mapSettings(this.currentMapId());
            return (D.doodads() || []).filter(d => d && d.bit && d.bit[0] === 3 && !d.line && !(d.model && d.model.path) &&
                D.Depth.resolve(d) !== 'below' && D.Layers.visibleInGame(d, settings));
        },

        // A doodad's first frame as PNG bytes.
        async framePng(d) {
            const bmp = D.loadBitmap(d.bit[1]);
            if (!bmp) return null;
            if (bmp.isReady && !bmp.isReady()) await new Promise(resolve => bmp.addLoadListener(resolve));
            const source = bmp._canvas || bmp._image || (bmp._baseTexture && bmp._baseTexture.resource && bmp._baseTexture.resource.source);
            if (!source) return null;
            const w = Math.max(1, Math.min(bmp.width, d.frameW || bmp.width)), h = Math.max(1, Math.min(bmp.height, d.frameH || bmp.height));
            const canvas = document.createElement('canvas');
            canvas.width = w; canvas.height = h;
            canvas.getContext('2d').drawImage(source, d.frameX || 0, d.frameY || 0, w, h, 0, 0, w, h);
            const encoded = canvas.toDataURL('image/png').split(',')[1];
            return encoded ? Buffer.from(encoded, 'base64') : null;
        },

        async saveMapGlb(options = {}) {
            const F = D.FS, scene = typeof SceneManager !== 'undefined' ? SceneManager._scene : null, spriteset = scene && scene._spriteset;
            if (!D.Compat.isTest() || !F.fs || !spriteset || !window.$gameMap) { this.showToast('Open a map in a playtest to save it as a 3D file.', 'error'); return null; }
            const values = options.values || await D.Ui.form({ title: 'Save 3D Map as File', ok: 'Save',
                text: "Writes this map's ground and standing doodads as one .glb file in screenshots/, for Blender, a trailer or a 3D print. The file carries this project's art: share it only where the art's licences allow.",
                fields: [
                    { key: 'scale', label: 'Ground picture size', type: 'select', value: '0.5', options: [{ value: '1', label: 'Full' }, { value: '0.5', label: 'Half' }, { value: '0.25', label: 'Quarter' }] },
                    { key: 'groundOnly', label: 'Ground only (no standing doodads)', type: 'checkbox', value: false }
                ] });
            if (!values) return null;
            const tw = $gameMap.tileWidth(), th = $gameMap.tileHeight(), tilesW = $gameMap.width(), tilesH = $gameMap.height();
            const standing = values.groundOnly ? [] : this.standingDoodads();
            // The ground's picture: tiles and floor decals; standing doodads are left out while it is drawn.
            const hidden = [];
            for (const sprite of spriteset._docsDoodadSprites || []) if (standing.includes(sprite._data) && sprite.renderable !== false) { sprite.renderable = false; hidden.push(sprite); }
            let canvas;
            try { canvas = D.MapExport.capture(spriteset, { scale: Number(values.scale) || 0.5 }).canvas; }
            finally { for (const sprite of hidden) sprite.renderable = true; }
            const picture = canvas.toDataURL('image/png').split(',')[1];
            const T = D.Terrain, grid = T.grid ? T.grid(true) : null;
            const ground = grid ? GW.groundFromTerrain(T.buildMesh(grid, 0, 0, tilesW, tilesH, tw, th, grid.style, T.light, 0), tw, th, tilesW * tw, tilesH * th) : GW.flatGround(tilesW, tilesH);
            ground.image = { bytes: Buffer.from(picture, 'base64'), mime: 'image/png' };
            ground.cutout = false;
            const meshes = [ground], groups = new Map();
            for (const d of standing) {
                const key = `${d.bit[1]}|${d.frameX || 0}|${d.frameY || 0}|${d.frameW || 0}|${d.frameH || 0}`;
                if (!groups.has(key)) groups.set(key, { d, items: [] });
                const sx = d.scaleX === undefined ? 1 : d.scaleX, sy = d.scaleY === undefined ? 1 : d.scaleY;
                groups.get(key).items.push({ x: d.x / tw, y: d.y / th, w: (d.frameW || 48) * Math.abs(sx) / tw, h: (d.frameH || 48) * Math.abs(sy) / th,
                    ground: grid ? T.heightAt(grid, d.x / tw, d.y / th, grid.style) : 0, flipX: sx < 0 });
            }
            for (const { d, items } of groups.values()) {
                const bytes = await (options.framePng || (x => this.framePng(x)))(d);
                if (bytes) meshes.push(GW.quads(String(d.bit[1]).split('/').pop().replace(/\.[^.]+$/, ''), items, { bytes, mime: 'image/png' }));
            }
            const glb = GW.glb(meshes);
            F.mkdirp('screenshots');
            const out = 'screenshots/' + this.mapGlbName($gameMap.mapId());
            F.atomicWriteFile(out, Buffer.from(glb.buffer, glb.byteOffset, glb.byteLength));
            this.showToast(`Saved ${out} (${Math.round(glb.byteLength / 1024)} KB, ${meshes.length} mesh(es)).`, 'success');
            try { if (typeof nw !== 'undefined' && nw.Shell) nw.Shell.showItemInFolder(F.path.resolve(out)); } catch (error) { /* no shell */ }
            return out;
        }
    });

    const menus = W.menus;
    W.menus = function() {
        const all = menus.call(this), map = all.find(menu => menu.id === 'map');
        if (map) map.items.push({ id: 'dd-map-glb-btn', icon: 'box', label: 'Save 3D Map as File', title: 'Write the ground and standing doodads as a .glb for Blender, trailers or 3D printing' });
        return all;
    };
    const bind = W.bindEvents;
    W.bindEvents = function() {
        const result = bind.apply(this, arguments), button = typeof document !== 'undefined' ? document.getElementById('dd-map-glb-btn') : null;
        if (button) button.onclick = () => { this.showMoreMenu(false); this.saveMapGlb(); };
        return result;
    };
})();
// @editor-only
//==========================================================
// SECTION 25I: IMPORT MAP (7.1.6)
//==========================================================
// Map → Import Map: choose a Tiled (.tmj/.json) or LDtk (.ldtk) file, pick a level, read what will be made,
// then Import. A new MZ map is written with the tile layers as picture layers (img/parallaxes), objects with
// a tile as doodads (pictures cut into img/doodads/<name>/), collision as painted walls, and "empty tiles are
// floor" on. Pictures are written whole or not at all; the map then opens. Close RPG Maker MZ's editor first:
// it rewrites MapInfos.json when it saves.
(function() {
    const D = DocsDoodads, W = D.Workspace, M = D.MapImport;
    const escapeHtml = value => D.Security.escapeHtml(String(value));

    Object.assign(W, {
        // Reads a map file and everything it names, relative to its folder. Returns { model, file, levels }.
        readImportMap(absolute, levelIndex = 0, io = {}) {
            const fs = io.fs || D.FS.fs, path = io.path || D.FS.path, zlib = io.zlib || require('zlib');
            const dir = path.dirname(absolute);
            const readFile = rel => JSON.parse(fs.readFileSync(path.resolve(dir, rel), 'utf8'));
            const json = JSON.parse(fs.readFileSync(absolute, 'utf8'));
            const name = path.basename(absolute);
            const inflate = (bytes, kind) => kind === 'gzip' ? zlib.gunzipSync(bytes) : zlib.inflateSync(bytes);
            if (/\.ldtk$/i.test(absolute) || (json && Array.isArray(json.levels) && json.defs)) {
                return { kind: 'ldtk', file: absolute, levels: M.levels(json), model: M.readLdtk(json, readFile, levelIndex, { file: name }) };
            }
            return { kind: 'tiled', file: absolute, levels: [], model: M.readTiled(json, readFile, { file: name, inflate }) };
        },

        importMapPlan(read, options = {}) {
            const infos = D.FS.readJson('data/MapInfos.json') || window.$dataMapInfos || [];
            const tile = window.$gameMap && $gameMap.tileWidth ? $gameMap.tileWidth() : 48;
            const tilesetId = options.tilesetId || (window.$dataMap && $dataMap.tilesetId) || 1;
            const base = options.baseName || D.FS.path.basename(read.file).replace(/\.[^.]+$/, '');
            return M.plan(read.model, { projectTile: tile, mapId: M.nextMapId(infos), baseName: base, mapName: options.mapName || base, tilesetId });
        },

        importImageUrl(dir, rel) {
            const absolute = D.FS.path.resolve(dir, rel);
            try { return require('url').pathToFileURL(absolute).href; } catch (error) { return 'file:///' + absolute.replace(/\\/g, '/'); }
        },

        loadImportImage(url) {
            return new Promise((resolve, reject) => {
                const image = new Image();
                image.onload = () => resolve(image);
                image.onerror = () => reject(new Error(`Could not read ${decodeURIComponent(String(url).split('/').pop())}`));
                image.src = url;
            });
        },

        // One file's pixels, drawn with its tiles' flips (Tiled: the diagonal first, then horizontal and vertical).
        drawImportFile(file, images) {
            const canvas = document.createElement('canvas');
            canvas.width = Math.max(1, Math.round(file.width)); canvas.height = Math.max(1, Math.round(file.height));
            const ctx = canvas.getContext('2d');
            ctx.imageSmoothingEnabled = false;
            ctx.globalAlpha = file.opacity === undefined ? 1 : file.opacity;
            for (const t of file.draws) {
                const image = images[t.image];
                if (!image) continue;
                ctx.save();
                ctx.translate(t.x + t.dw / 2, t.y + t.dh / 2);
                ctx.scale(t.flipX ? -1 : 1, t.flipY ? -1 : 1);
                if (t.diagonal) ctx.transform(0, 1, 1, 0, 0, 0);
                ctx.drawImage(image, t.sx, t.sy, t.w, t.h, -t.dw / 2, -t.dh / 2, t.dw, t.dh);
                ctx.restore();
            }
            const encoded = canvas.toDataURL('image/png').split(',')[1];
            if (!encoded) throw new Error(`${file.path} could not be drawn.`);
            return Buffer.from(encoded, 'base64');
        },

        // Pictures to temporary names first, then all renamed; any failure removes what was written.
        writeImportFiles(entries) {
            const F = D.FS, fs = F.fs, path = F.path, stamp = `.ddimport-${Date.now().toString(36)}`;
            const temps = [], done = [];
            try {
                for (const e of entries) if (F.existsSync(e.path)) throw new Error(`${e.path} already exists.`);
                for (const e of entries) {
                    F.mkdirp(path.dirname(e.path));
                    fs.writeFileSync(e.path + stamp, e.bytes);
                    temps.push(e.path + stamp);
                }
                for (const e of entries) { fs.renameSync(e.path + stamp, e.path); done.push(e.path); }
                return { ok: true, written: done };
            } catch (error) {
                for (const p of temps) { try { if (F.existsSync(p)) fs.unlinkSync(p); } catch (ignored) { /* gone */ } }
                for (const p of done) { try { fs.unlinkSync(p); } catch (ignored) { /* gone */ } }
                return { ok: false, error: error.message || String(error) };
            }
        },

        async runMapImport(read, plan, io = {}) {
            const F = D.FS;
            if (!D.Compat.isTest() || !F.fs) { this.showToast('Import Map works only in a playtest.', 'error'); return null; }
            const progress = D.Ui.progress('Importing map', { delay: 300 });
            try {
                const dir = F.path.dirname(read.file), images = {};
                const sources = Array.from(new Set(plan.files.flatMap(f => f.draws.map(t => t.image))));
                progress.update(0, sources.length + plan.files.length, 'reading tilesets');
                for (const [i, rel] of sources.entries()) {
                    images[rel] = await (io.loadImage || (url => this.loadImportImage(url)))(this.importImageUrl(dir, rel));
                    progress.update(i + 1, sources.length + plan.files.length);
                }
                const entries = [];
                for (const [i, file] of plan.files.entries()) {
                    entries.push({ path: file.path, bytes: (io.draw || ((f, imgs) => this.drawImportFile(f, imgs)))(file, images) });
                    progress.update(sources.length + i + 1, sources.length + plan.files.length, file.path.split('/').pop());
                    await new Promise(resolve => setTimeout(resolve, 0));
                }
                const mapFile = D.Persistence.mapFilePath(plan.mapId);
                if (F.existsSync(mapFile)) throw new Error(`${mapFile} already exists; close RPG Maker MZ and try again.`);
                const written = this.writeImportFiles(entries);
                if (!written.ok) throw new Error(written.error);
                const infos = (F.readJson('data/MapInfos.json') || window.$dataMapInfos || []).slice();
                infos[plan.mapId] = plan.mapInfo;
                F.createTimestampedBackup('data/MapInfos.json');
                if (!F.atomicWriteJson(mapFile, plan.map, 0) || !F.atomicWriteJson('data/MapInfos.json', infos, 0)) {
                    for (const p of written.written) { try { F.fs.unlinkSync(p); } catch (ignored) { /* gone */ } }
                    try { if (F.existsSync(mapFile)) F.fs.unlinkSync(mapFile); } catch (ignored) { /* gone */ }
                    throw new Error('Could not write the new map files.');
                }
                window.$dataMapInfos = infos;
                this.applyImportData(plan);
                D.Persistence.saveMapOnly(plan.mapId);
                if (D.AssetIndex && D.AssetIndex.indexPaths) await D.AssetIndex.indexPaths(written.written.filter(p => /^img\/doodads\//.test(p)), { save: true });
                this.showToast(`Imported Map ${String(plan.mapId).padStart(3, '0')}: ${plan.files.length} picture(s), ${plan.doodads.length} doodad(s). Reopen the project in MZ to see it in the map list.`, 'success');
                return plan.mapId;
            } catch (error) {
                this.showToast(`Import Map stopped; nothing was kept: ${error.message || error}`, 'error');
                return null;
            } finally {
                progress.finish();
            }
        },

        // The doodads, picture layers and walls of the new map, in the plugin's data.
        applyImportData(plan) {
            const data = window.$dataDocsDoodads = window.$dataDocsDoodads || {};
            data[plan.mapId] = plan.doodads.map(row => {
                const d = D.standardStruct();
                d.bit = [3, row.path]; d.x = row.x; d.y = row.y; d.frameW = row.frameW; d.frameH = row.frameH;
                if (row.scaleX !== 1) d.scaleX = row.scaleX;
                if (row.scaleY !== 1) d.scaleY = row.scaleY;
                if (row.name) d.name = row.name;
                d.depth = 'sorted';
                return d;
            });
            D.Lighting.setMapSettings(plan.mapId, { layers2d: plan.layers2d, emptyIsFloor: true });
            if (plan.walls) D.Walls.set(plan.mapId, plan.walls);
            D.Persistence.dirtyDoodads = true;
        },

        closeMapImport() {
            const card = typeof document !== 'undefined' && document.getElementById ? document.getElementById('dd-map-import') : null;
            if (card && card.parentNode) card.parentNode.removeChild(card);
            this._mapImport = null;
        },

        renderMapImportPlan(state) {
            const plan = state.plan;
            if (!plan) return state.error ? `<div style="color:var(--dd-danger, #f87171);">${escapeHtml(state.error)}</div>` : '<div>Choose a Tiled (.tmj, .json) or LDtk (.ldtk) file.</div>';
            const layers = plan.files.filter(f => f.kind === 'layer'), pieces = plan.files.filter(f => f.kind === 'piece');
            return `<div><b>Map ${String(plan.mapId).padStart(3, '0')}</b>, ${plan.width} × ${plan.height} tiles</div>
                <div>${layers.length} picture layer(s): ${layers.map(f => escapeHtml(f.path.split('/').pop())).join(', ') || 'none'}</div>
                <div>${plan.doodads.length} doodad(s) from ${pieces.length} picture(s) in img/doodads/</div>
                <div>${plan.walls ? 'Collision painted from the collision layers.' : 'No collision layer.'} Empty tiles are floor.</div>
                ${plan.notices.map(n => `<div style="color:var(--dd-muted);">${escapeHtml(n)}</div>`).join('')}`;
        },

        openMapImport() {
            if (typeof document === 'undefined') return null;
            this.closeMapImport();
            const state = this._mapImport = { read: null, plan: null, error: '', level: 0 };
            const card = document.createElement('div');
            card.id = 'dd-map-import'; card.className = 'dd-glass';
            card.style.cssText = 'position:fixed;top:80px;right:20px;width:360px;max-height:75vh;overflow:auto;padding:12px;z-index:10040;font-size:11px;display:flex;flex-direction:column;gap:6px;';
            const render = () => {
                card.innerHTML = `<div class="dd-panel-head">Import Map <button class="dd-btn" id="dd-map-import-close" type="button">Close</button></div>
                    <div style="color:var(--dd-muted);">Tile layers become picture layers, objects with a tile become doodads, collision layers become painted collision. Close RPG Maker MZ's editor first.</div>
                    <input id="dd-map-import-file" type="file" accept=".tmj,.json,.ldtk">
                    ${state.read && state.read.levels.length ? `<select id="dd-map-import-level">${state.read.levels.map(l => `<option value="${l.index}"${l.index === state.level ? ' selected' : ''}>${escapeHtml(l.name)}</option>`).join('')}</select>` : ''}
                    ${this.renderMapImportPlan(state)}
                    <button class="dd-btn dd-btn-primary" id="dd-map-import-run" type="button"${state.plan ? '' : ' disabled'}>Import</button>`;
                const node = id => document.getElementById(id);
                node('dd-map-import-close').onclick = () => this.closeMapImport();
                node('dd-map-import-file').onchange = event => {
                    const file = event.target.files && event.target.files[0];
                    if (!file || !file.path) { state.error = 'Choose a file on this computer.'; render(); return; }
                    state.file = file.path; state.level = 0; load();
                };
                const level = node('dd-map-import-level');
                if (level) level.onchange = () => { state.level = Number(level.value) || 0; load(); };
                node('dd-map-import-run').onclick = async () => {
                    if (!state.plan) return;
                    const mapId = await this.runMapImport(state.read, state.plan);
                    if (mapId) { this.closeMapImport(); if (this.goToMap) this.goToMap(mapId); }
                };
            };
            const load = () => {
                try {
                    state.read = this.readImportMap(state.file, state.level);
                    state.plan = this.importMapPlan(state.read);
                    state.error = '';
                } catch (error) { state.plan = null; state.error = error.message || String(error); }
                render();
            };
            document.body.appendChild(card);
            render();
            return card;
        }
    });

    const menus = W.menus;
    W.menus = function() {
        const all = menus.call(this), map = all.find(menu => menu.id === 'map');
        if (map) map.items.push({ id: 'dd-map-import-btn', icon: 'folder', label: 'Import Map', title: 'Make a new map from a Tiled or LDtk file' });
        return all;
    };
    const bind = W.bindEvents;
    W.bindEvents = function() {
        const result = bind.apply(this, arguments), button = typeof document !== 'undefined' ? document.getElementById('dd-map-import-btn') : null;
        if (button) button.onclick = () => { this.showMoreMenu(false); this.openMapImport(); };
        return result;
    };

    // Map settings: the switch the importer turns on, for parallax maps made by hand too.
    W.mapSections.push({
        render(settings) {
            return `<details style="border-top: 1px solid var(--dd-line-soft); padding-top: 6px; margin-top: 6px;">
                <summary style="font-size: 11px; font-weight: bold;">Picture map</summary>
                <label style="font-size: 10px;"><input id="dd-empty-floor" type="checkbox"${settings.emptyIsFloor === true ? ' checked' : ''} /> Empty tiles are floor</label>
                <div style="font-size: 10px; color: var(--dd-faint);">For maps drawn with picture layers: a tile with nothing on it can be walked on. Paint collision where it can't.</div>
            </details>`;
        },
        bind() {
            const control = document.getElementById('dd-empty-floor');
            if (control) control.onchange = () => this.setMapSetting('emptyIsFloor', control.checked ? true : undefined);
        }
    });
})();
// @editor-only
//==========================================================
// SECTION 25r: BACKGROUND AND OVERLAY LAYERS (MAP SETTINGS)
//==========================================================
// The map's picture layers for flat maps (DocsDoodads.MapLayers): a row each with its picture (from
// img/parallaxes, or fog banks), where it goes, how it follows the camera, scrolls, zooms, repeats and
// blends. The map shows changes straight away.
Object.assign(DocsDoodads.Workspace, {
    mapLayers2d() {
        const list = (DocsDoodads.Lighting.mapSettings(this.currentMapId()) || {}).layers2d;
        return Array.isArray(list) ? JSON.parse(JSON.stringify(list)) : [];
    },

    setMapLayers2d(list) {
        this.setMapSetting('layers2d', list.length ? list.map(l => DocsDoodads.MapLayers.normalize(l)) : undefined);
    },

    addMapLayer2d(image) {
        const list = this.mapLayers2d();
        const fog = image === '#fog';
        list.push(DocsDoodads.MapLayers.normalize(fog
            ? { image: '#fog', place: 'front', follow: 1, scrollX: 0.3, zoom: 2, opacity: 0.45, blend: 'screen', wind: true }
            : { image: image || '', place: 'back' }));
        this.setMapLayers2d(list);
        return list.length - 1;
    },

    // The pictures in img/parallaxes the Item Bag knows, for the picture box's suggestions.
    parallaxNames() {
        const list = (DocsDoodads.AssetIndex && DocsDoodads.AssetIndex.list) || [];
        return list.map(a => String(a.path || '').replace(/\\/g, '/')).filter(p => /^img\/parallaxes\//i.test(p))
            .map(p => p.replace(/^img\/parallaxes\//i, '').replace(/\.(png|webp)$/i, '')).sort();
    }
});

DocsDoodads.Workspace.mapSections.push({
    render() {
        const L = DocsDoodads.MapLayers;
        const layers = this.mapLayers2d().map(l => L.normalize(l));
        const option = (value, label, current) => `<option value="${escapeHtml(String(value))}"${String(value) === String(current) ? ' selected' : ''}>${escapeHtml(label)}</option>`;
        const num = (id, value, step, title) => `<input type="number" id="${id}" value="${value}" step="${step}" title="${escapeHtml(title)}" style="width: 100%;" />`;
        const rows = layers.map((l, i) => `
            <div style="border: 1px solid var(--dd-line-soft); border-radius: 8px; padding: 5px; display: flex; flex-direction: column; gap: 4px;">
                <div style="display: flex; gap: 4px; align-items: center;">
                    <input type="text" id="dd-ml-${i}-image" list="dd-ml-pictures" value="${escapeHtml(l.image)}" placeholder="img/parallaxes picture, or #fog" title="Picture (img/parallaxes), or #fog for fog banks" style="flex: 1; min-width: 0;" />
                    <button class="dd-btn" id="dd-ml-${i}-up" type="button" title="Draw it earlier (further back)" style="padding: 2px 6px;"${i === 0 ? ' disabled' : ''}>↑</button>
                    <button class="dd-btn" id="dd-ml-${i}-del" type="button" title="Remove this layer" style="padding: 2px 6px;">${DocsDoodads.Ui.icon('trash', 1)}</button>
                </div>
                <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 4px; font-size: 10px; color: var(--dd-muted);">
                    <div>Where<select id="dd-ml-${i}-place" style="width: 100%;">${L.places.map(p => option(p.value, p.label, l.place)).join('')}</select></div>
                    <div>Blend<select id="dd-ml-${i}-blend" style="width: 100%;">${L.blends.map(b => option(b.value, b.label, l.blend)).join('')}</select></div>
                    <div>Follows the camera${num(`dd-ml-${i}-follow`, l.follow, 0.05, '0 = fixed to the screen, 1 = moves with the map, 0.5 = halfway (far away)')}</div>
                    <div>Zoom${num(`dd-ml-${i}-zoom`, l.zoom, 0.1, 'How big the picture is drawn')}</div>
                    <div>Scrolls across (px/frame)${num(`dd-ml-${i}-scrollX`, l.scrollX, 0.1, 'Moves on its own; negative is left')}</div>
                    <div>Scrolls down (px/frame)${num(`dd-ml-${i}-scrollY`, l.scrollY, 0.1, 'Moves on its own; negative is up')}</div>
                    <div>Opacity${num(`dd-ml-${i}-opacity`, l.opacity, 0.05, '0 to 1')}</div>
                    <div style="display: flex; flex-direction: column; gap: 2px; justify-content: flex-end;">
                        <label style="display: flex; gap: 4px; align-items: center;"><input type="checkbox" id="dd-ml-${i}-loopX" ${l.loopX ? 'checked' : ''} /> Repeat across</label>
                        <label style="display: flex; gap: 4px; align-items: center;"><input type="checkbox" id="dd-ml-${i}-loopY" ${l.loopY ? 'checked' : ''} /> Repeat down</label>
                        <label style="display: flex; gap: 4px; align-items: center;" title="World > Weather on Flat Maps"><input type="checkbox" id="dd-ml-${i}-wind" ${l.wind ? 'checked' : ''} /> Drifts with the wind</label>
                    </div>
                </div>
            </div>`).join('');
        return `
            <details id="dd-ml-sec" ${this._openMapLayers ? 'open' : ''} style="border-top: 1px solid var(--dd-line-soft); padding-top: 6px; margin-top: 6px;">
                <summary style="cursor: pointer; font-size: 11px; font-weight: bold; color: var(--dd-muted);">Background and Overlay Layers (flat map)</summary>
                <datalist id="dd-ml-pictures">${['#fog'].concat(this.parallaxNames()).map(n => `<option value="${escapeHtml(n)}"></option>`).join('')}</datalist>
                <div style="display: flex; flex-direction: column; gap: 6px; margin-top: 6px;">
                    ${rows || '<div style="font-size: 10px; color: var(--dd-faint); line-height: 1.4;">No layers. Add distant mountains behind the tiles, or clouds and fog over them; each scrolls on its own.</div>'}
                    <div style="display: flex; gap: 4px;">
                        <button class="dd-btn" id="dd-ml-add" type="button">${DocsDoodads.Ui.icon('plus', 1)} Add a Layer</button>
                        <button class="dd-btn" id="dd-ml-add-fog" type="button" title="Soft fog banks drifting over the map">${DocsDoodads.Ui.icon('plus', 1)} Fog Banks</button>
                    </div>
                </div>
            </details>`;
    },
    bind() {
        const byId = id => document.getElementById(id);
        const details = byId('dd-ml-sec');
        if (details) details.ontoggle = () => { this._openMapLayers = details.open; };
        const again = () => { this._openMapLayers = true; this.refreshInspector(); };
        const add = byId('dd-ml-add');
        if (add) add.onclick = () => {
            const names = this.parallaxNames();
            this.addMapLayer2d(names[0] || '');
            again();
        };
        const fog = byId('dd-ml-add-fog');
        if (fog) fog.onclick = () => { this.addMapLayer2d('#fog'); again(); };
        this.mapLayers2d().forEach((l, i) => {
            const change = (field, value) => { const list = this.mapLayers2d(); list[i] = Object.assign({}, list[i], { [field]: value }); this.setMapLayers2d(list); };
            for (const field of ['image', 'place', 'blend']) {
                const input = byId(`dd-ml-${i}-${field}`);
                if (input) input.onchange = e => change(field, e.target.value);
            }
            for (const field of ['follow', 'zoom', 'scrollX', 'scrollY', 'opacity']) {
                const input = byId(`dd-ml-${i}-${field}`);
                if (input) input.onchange = e => { if (String(e.target.value).trim() !== '') change(field, Number(e.target.value)); };
            }
            for (const field of ['loopX', 'loopY', 'wind']) {
                const input = byId(`dd-ml-${i}-${field}`);
                if (input) input.onchange = e => change(field, Boolean(e.target.checked));
            }
            const up = byId(`dd-ml-${i}-up`);
            if (up) up.onclick = () => { const list = this.mapLayers2d(); if (i > 0) { [list[i - 1], list[i]] = [list[i], list[i - 1]]; this.setMapLayers2d(list); } again(); };
            const del = byId(`dd-ml-${i}-del`);
            if (del) del.onclick = () => { const list = this.mapLayers2d(); list.splice(i, 1); this.setMapLayers2d(list); again(); };
        });
    }
});

// The map's camera bounds: while the player stands on one of these regions, the camera stays inside the
// area that region covers (flat maps; World > Camera on Flat Maps has the easing).
DocsDoodads.Workspace.mapSections.push({
    render(mapSettings) {
        const list = mapSettings && Array.isArray(mapSettings.cameraBounds) ? mapSettings.cameraBounds : [];
        return `
            <details id="dd-cam2d-sec" ${this._openCam2d ? 'open' : ''} style="border-top: 1px solid var(--dd-line-soft); padding-top: 6px; margin-top: 6px;">
                <summary style="cursor: pointer; font-size: 11px; font-weight: bold; color: var(--dd-muted);">Camera (flat map)</summary>
                <div style="display: flex; flex-direction: column; gap: 5px; margin-top: 6px; font-size: 10px; color: var(--dd-muted);">
                    <div>Keep the camera inside these regions' areas (numbers, e.g. 5, 7)
                        <input type="text" id="dd-cam2d-regions" value="${escapeHtml(list.join(', '))}" style="width: 100%;" /></div>
                    <div style="color: var(--dd-faint); line-height: 1.4;">Paint a room or corridor with a region (Regions tool) and list it here: while the player is on it, the view stops at its edges. The 2D Camera Path and 2D Camera Follow commands move it in cutscenes.</div>
                </div>
            </details>`;
    },
    bind() {
        const details = document.getElementById('dd-cam2d-sec');
        if (details) details.ontoggle = () => { this._openCam2d = details.open; };
        const input = document.getElementById('dd-cam2d-regions');
        if (input) input.onchange = e => {
            const ids = String(e.target.value || '').split(/[\s,;]+/).map(n => parseInt(n, 10)).filter(n => n > 0 && n < 256);
            this.setMapSetting('cameraBounds', ids.length ? Array.from(new Set(ids)) : undefined);
        };
    }
});
// @editor-only
//==========================================================
// SECTION 25f: MAP PICTURE CACHE AND UI
//==========================================================
(function(MapThumb, Workspace) {
    MapThumb._pending = {};
    MapThumb._tokens = {};
    MapThumb._urlCache = new Map();
    MapThumb._volatile = new Map();
    MapThumb._invalid = new Set();
    MapThumb.maxUrls = 32;
    MapThumb.maxVolatile = 8;

    MapThumb.status = function(mapId) {
        const picturePath = this.cachePath(mapId), sourcePath = this.sourcePath(mapId);
        const state = this.freshness(DocsDoodads.FS.stat(sourcePath), DocsDoodads.FS.stat(picturePath));
        if (this._invalid.has(Number(mapId))) state.fresh = false;
        return Object.assign(state, { path: picturePath, sourcePath });
    };

    MapThumb.url = function(mapId) {
        if (this._volatile.has(Number(mapId))) {
            const value = this._volatile.get(Number(mapId));
            this._volatile.delete(Number(mapId));
            this._volatile.set(Number(mapId), value);
            return value;
        }
        const status = this.status(mapId);
        if (!status.fresh) return '';
        const stat = DocsDoodads.FS.stat(status.path);
        const key = `${mapId}:${this.revision(stat)}`;
        if (this._urlCache.has(key)) {
            const value = this._urlCache.get(key);
            this._urlCache.delete(key);
            this._urlCache.set(key, value);
            return value;
        }
        const value = encodeURI(status.path.replace(/\\/g, '/')) + '?v=' + encodeURIComponent(this.revision(stat));
        while (this._urlCache.size >= this.maxUrls) this._urlCache.delete(this._urlCache.keys().next().value);
        this._urlCache.set(key, value);
        return value;
    };

    MapThumb.write = function(mapId, canvas, volatile) {
        const dataUrl = canvas && canvas.toDataURL ? canvas.toDataURL('image/png') : '';
        if (volatile && /^data:image\/png;base64,/i.test(dataUrl)) {
            while (this._volatile.size >= this.maxVolatile) this._volatile.delete(this._volatile.keys().next().value);
            this._volatile.set(Number(mapId), dataUrl);
            return true;
        }
        const bytes = this.pngBytes(dataUrl);
        if (!bytes) return false;
        if (!DocsDoodads.FS.existsSync(this.cacheDir)) DocsDoodads.FS.mkdirp(this.cacheDir);
        DocsDoodads.FS.atomicWriteFile(this.cachePath(mapId), bytes);
        this._volatile.delete(Number(mapId));
        this._invalid.delete(Number(mapId));
        for (const key of Array.from(this._urlCache.keys())) if (key.indexOf(mapId + ':') === 0) this._urlCache.delete(key);
        return true;
    };

    MapThumb.invalidate = function(mapId) {
        mapId = Number(mapId);
        this._tokens[mapId] = (this._tokens[mapId] || 0) + 1;
        this._volatile.delete(mapId);
        this._invalid.add(mapId);
        for (const key of Array.from(this._urlCache.keys())) if (key.indexOf(mapId + ':') === 0) this._urlCache.delete(key);
        const path = this.cachePath(mapId);
        let removed = true;
        try {
            if (DocsDoodads.FS.existsSync(path)) DocsDoodads.FS.fs.unlinkSync(path);
        } catch (error) {
            DocsDoodads.Core.log(`Map ${mapId} picture cache could not be invalidated.`, error);
            removed = false;
        }
        if (Workspace.refreshMapThumbUi) Workspace.refreshMapThumbUi(mapId);
        return removed;
    };

    MapThumb.invalidateMany = function(mapIds) {
        for (const mapId of mapIds || []) this.invalidate(mapId);
    };

    MapThumb.clearVolatile = function(mapIds) {
        if (!mapIds) { this._volatile.clear(); return; }
        for (const mapId of mapIds) this._volatile.delete(Number(mapId));
    };

    MapThumb.shouldStayVolatile = function(mapId) {
        const persistence = DocsDoodads.Persistence;
        return Boolean(persistence.dirtyDoodads || persistence.mapHasUnsaved(mapId));
    };

    MapThumb.stateRevision = function(mapId) {
        const persistence = DocsDoodads.Persistence;
        return `${persistence.changeCount}:${persistence.dirtyDoodads ? 1 : 0}:${persistence.mapHasUnsaved(mapId) ? 1 : 0}`;
    };

    MapThumb.request = function(mapId, options) {
        options = options || {};
        mapId = Number(mapId);
        try {
            if (!editorMode || !DocsDoodads.Compat.isTest() || !DocsDoodads.Compat.isNwjs() || !DocsDoodads.FS.fs) return Promise.resolve(false);
            if (!window.$gameMap || Number(window.$gameMap.mapId()) !== mapId) return Promise.resolve(false);
            const volatile = this.shouldStayVolatile(mapId);
            if (!options.force && !volatile && this.status(mapId).fresh) return Promise.resolve(true);
            const stateRevision = this.stateRevision(mapId);
            const waiting = this._pending[mapId];
            if (waiting) {
                if (waiting.revision === stateRevision && waiting.token === this._tokens[mapId]) return waiting.promise;
                return waiting.promise.then(() => this.request(mapId, { force: true }));
            }
            const snapshot = this.snapshotCurrent(mapId);
            if (!snapshot) return Promise.resolve(false);
            snapshot.unsaved = volatile;
            const sourceRevision = this.revision(DocsDoodads.FS.stat(this.sourcePath(mapId)));
            const token = this._tokens[mapId] = (this._tokens[mapId] || 0) + 1;
            let rendering;
            try { rendering = this.render(snapshot); } catch (error) { rendering = Promise.reject(error); }
            const entry = { promise: null, revision: stateRevision, token };
            const promise = Promise.resolve(rendering).then(canvas => {
                if (this._tokens[mapId] !== token || this.stateRevision(mapId) !== stateRevision) return false;
                if (this.revision(DocsDoodads.FS.stat(this.sourcePath(mapId))) !== sourceRevision) return false;
                const written = this.write(mapId, canvas, snapshot.unsaved);
                if (canvas) canvas.width = canvas.height = 1;
                if (written && Workspace.refreshMapThumbUi) Workspace.refreshMapThumbUi(mapId);
                return written;
            }).catch(error => {
                DocsDoodads.Core.log(`Map ${mapId} picture was not made.`, error);
                return false;
            }).then(result => {
                if (this._pending[mapId] === entry) delete this._pending[mapId];
                return result;
            });
            entry.promise = promise;
            this._pending[mapId] = entry;
            return promise;
        } catch (error) {
            DocsDoodads.Core.log(`Map ${mapId} picture was not queued.`, error);
            return Promise.resolve(false);
        }
    };

    MapThumb.markup = function(mapId, name, className) {
        const label = String(name || `Map ${mapId}`);
        const url = this.url(mapId);
        if (url) return `<img class="${className || 'dd-map-thumb'}" src="${escapeHtml(url)}" alt="${escapeHtml(label)} map preview" />`;
        return `<span class="${className || 'dd-map-thumb'} dd-map-thumb-empty" role="img" aria-label="${escapeHtml(label)} has no map preview yet">${escapeHtml(label)}</span>`;
    };

    MapThumb.decorateTooltip = function(element, tooltip) {
        if (!element || !tooltip || !element.getAttribute || !tooltip.appendChild) return tooltip;
        const mapId = Number(element.getAttribute('data-dd-map-thumb'));
        if (!(mapId > 0)) return tooltip;
        const name = element.getAttribute('data-dd-map-name') || `Map ${mapId}`;
        const url = this.url(mapId);
        const preview = document.createElement(url ? 'img' : 'div');
        preview.className = url ? 'dd-map-tip-picture' : 'dd-map-tip-picture dd-map-thumb-empty';
        if (url) { preview.src = url; preview.alt = `${name} map preview`; }
        else { preview.textContent = name; preview.setAttribute('role', 'img'); preview.setAttribute('aria-label', `${name} has no map preview yet`); }
        tooltip.insertBefore ? tooltip.insertBefore(preview, tooltip.firstChild || null) : tooltip.appendChild(preview);
        return tooltip;
    };

    Object.assign(Workspace, {
        mapThumb(mapId, options) {
            return MapThumb.request(mapId, options);
        },

        mapThumbMarkup(mapId, name, className) {
            return MapThumb.markup(mapId, name, className);
        },

        refreshMapThumbUi(mapId) {
            mapId = Number(mapId);
            if (this.mounted && this.renderMapTabs) this.renderMapTabs();
            if (typeof document !== 'undefined') {
                const select = document.getElementById('dd-map-goto');
                const preview = document.getElementById('dd-map-goto-preview');
                if (select && preview && Number(select.value) === mapId) {
                    const entry = this.mapEntries().find(map => map.id === mapId);
                    preview.innerHTML = this.mapThumbMarkup(mapId, entry && entry.name);
                }
            }
            if (typeof this._worldThumbRefresh === 'function') this._worldThumbRefresh(mapId);
        }
    });
})(DocsDoodads.MapThumb, DocsDoodads.Workspace);

DocsDoodads.Ui.css += `
.dd-map-thumb { width: 44px; height: 32px; object-fit: cover; flex: none; border-radius: 4px; border: 1px solid var(--dd-line); image-rendering: pixelated; background: var(--dd-field); }
.dd-map-thumb-empty { display: inline-flex; align-items: center; justify-content: center; overflow: hidden; padding: 2px; box-sizing: border-box; color: var(--dd-faint); font-size: 8px; line-height: 1.1; text-align: center; }
.dd-map-tip-picture { display: flex; width: 256px; max-width: 55vw; max-height: 256px; object-fit: contain; margin-bottom: 6px; border-radius: 5px; image-rendering: pixelated; }
.dd-map-tip-picture.dd-map-thumb-empty { min-height: 72px; align-items: center; justify-content: center; background: var(--dd-field); }
`;
