            const rng = this.previewRng(tool === 'brush' ? '_scatterRng' : '_biomeRng');
            const raw = tool === 'biome' ? D.Biome.find(settings.biomeId, D.World.get('biomes.list') || []) : null;
            if (tool === 'biome' && !raw) return [];
