            label.style.cssText = 'flex-direction: row; align-items: center; gap: 6px;';
            label.innerHTML = `<input type="checkbox" id="dd-look-motion" ${U.prefs().lessMotion === true ? 'checked' : ''} /> Less motion (no animations)`;
